# Every preset the markup actually offers, and the endpoint it must resolve to.
# A typo in either the markup or the mapping must not silently route a cover
# request to the direct Music 3 adapter.
PRESET_ENDPOINTS = {
    "balanced": "music",
    "songplanner-invented": "songplanner",
    "songplanner-known": "songplanner",
}


def markup_preset_values() -> list[str]:
    """The `<option>` values of the Song workspace preset select, read from the markup."""
    select = re.search(
        r'<select name="preset".*?</select>', INDEX_HTML.read_text(encoding="utf-8"), re.DOTALL
    )
    assert select, "the Song workspace form no longer has a preset select"
    return re.findall(r'<option value="([^"]+)"', select.group(0))


def app_js_block(anchor: str, terminator: str = "\n}") -> str:
    """The source of one app.js function or handler, for the DOM code no import can reach."""
    source = APP_JS.read_text(encoding="utf-8")
    assert anchor in source, anchor
    return source.split(anchor, 1)[1].split(terminator, 1)[0]


def app_js_function(name: str) -> str:
    """The **whole** source of one top-level `app.js` function, so it can be executed.

    `app_js_block` hands back a body for reading; this hands back a declaration for running. The
    terminator is a `}` in the first column, which in this file only ever closes a top-level
    function -- and the check that the slice really is a function is that node compiles it, which
    is a loud failure rather than a quiet pass if the extraction ever stops lining up.
    """
    source = APP_JS.read_text(encoding="utf-8")
    anchor = f"function {name}("
    assert source.count("\n" + anchor) == 1, name
    return anchor + source.split("\n" + anchor, 1)[1].split("\n}\n", 1)[0] + "\n}"


def without_comments(source: str) -> str:
    """`source` with its `//` comment lines dropped, so assertions are about code only."""
    return "\n".join(line for line in source.splitlines() if not line.strip().startswith("//"))


class _MarkupChildren(HTMLParser):
    """Every direct child of the one element carrying a class, read off `index.html` itself.

    A depth counter rather than a regex, because "a direct child" is a structural question and the
    markup in this workspace nests several levels of comment and control inside a single row. The
    whole document is walked, so an unbalanced tag surfaces as a leftover on the stack rather than
    as a quietly short list of children.
    """

    VOID: ClassVar[set[str]] = {
        "area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "param",
        "source", "track", "wbr",
    }

    def __init__(self, wanted: str):
        super().__init__(convert_charrefs=True)
        self.wanted = wanted
        self.stack: list[str] = []
        self.depth: int | None = None
        self.children: list[dict] = []

    def handle_starttag(self, tag, attrs):
        if tag in self.VOID:
            return
        bag = dict(attrs)
        classes = (bag.get("class") or "").split()
        if self.depth is not None and len(self.stack) == self.depth:
            self.children.append({"tag": tag, "classes": classes, "attributes": bag})
        self.stack.append(tag)
        if self.depth is None and self.wanted in classes:
            self.depth = len(self.stack)

    def handle_endtag(self, tag):
        if tag in self.VOID:
            return
        if self.depth is not None and len(self.stack) == self.depth:
            self.depth = None
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        elif tag in self.stack:
            while self.stack and self.stack.pop() != tag:
                pass


def markup_children(class_name: str) -> list[dict]:
    """The direct children of `index.html`'s one element carrying `class_name`."""
    walk = _MarkupChildren(class_name)
    walk.feed(INDEX_HTML.read_text(encoding="utf-8"))
    assert not walk.stack, (
        ("index.html does not close every tag it opens, so nothing structural can be read "
         "off it"),
        walk.stack,
    )
    assert walk.children, f"no element in index.html carries the {class_name} class"
    return walk.children


def css_track_list(value: str) -> list[str]:
    """One `grid-template-*` value as its tracks, splitting on top-level whitespace only -- the
    comma inside `minmax(120px, 1fr)` belongs to the track rather than between two of them."""
    tracks: list[str] = []
    current = ""
    depth = 0
    for character in value:
        if character == "(":
            depth += 1
        elif character == ")":
            depth -= 1
        if character.isspace() and depth == 0:
            if current:
                tracks.append(current)
            current = ""
        else:
            current += character
    if current:
        tracks.append(current)
    return tracks


def scoped_control_group(document_tab: str) -> str:
    """The markup of the controls group scoped to one document tab.

    The class list is matched loosely because one group carries `active` in the markup: the
    Brief's tab is the one open on load and the tab handler only runs on a click, so its pair
    of controls would otherwise be invisible until the Director switched tabs and came back.
    """
    group = re.search(
        rf'<div class="document-scoped[^"]*" data-doc-controls="{document_tab}">.*?</div>',
        INDEX_HTML.read_text(encoding="utf-8"),
        re.DOTALL,
    )
    assert group, f"no per-document controls group is scoped to the {document_tab} tab"
    return group.group(0)


def run_module(script: str):
    # Decoded as UTF-8 explicitly. `text=True` alone decodes node's stdout with the *platform*
    # encoding, which on Windows is a code page that mangles every typographic character the
    # workspace draws — the ellipsis in "Attach asset…", the em dashes in the mode select — into
    # replacement characters, so an assertion about a string the Director really sees fails for a
    # reason that has nothing to do with the code under test. `batch.READINESS_REFUSAL` is
    # deliberately ASCII to dodge exactly this; that is the right call for a string two languages
    # must agree on character for character, and the wrong one to force on the whole interface.
    result = subprocess.run(
        ["node", "--input-type=module", "--eval", script],
        check=True,
        capture_output=True,
        text=True,
        encoding="utf-8",
    )
    return json.loads(result.stdout)


#: The palette tokens a canvas drawing reads off its own computed style, answered with sentinels
#: rather than with the real hexes: what is being asserted is *which* token a stroke was drawn in,
#: and a hex would make that a second copy of the stylesheet.
DRAWING_TOKENS = {"--dim": "DIM", "--blue": "BLUE", "--acid": "ACID"}


def recorded_drawing(name: str, plan: str, imports: str, device_pixels: float = 1) -> dict:
    """Execute one of `app.js`'s canvas drawings and hand back the calls it made, in order.

    **A recording context, not a canvas.** It records every method call and every property write
    and simulates nothing -- no pixels, no paths, no state machine -- because the moment a stub
    starts modelling a canvas it is a second implementation and the test is about the stub.

    This exists because the two drawings in this workspace were guarded by a substring scan of
    their own source and by nothing else: the stub DOM has no `getContext`, so no test called
    either of them. A scan cannot see *order or presence of calls*, which is exactly what both of
    the readout's shipped regressions were about -- the silenced-passage ground bar going missing,
    and the rest hairline being drawn in front of the fill that then painted over it. Both were
    found by a human looking at the picture; both are executable here.

    `plan` is a JavaScript expression for the plan the drawing is handed -- built from `api.js`'s
    own plan function, so the geometry under test is the geometry that ships. `imports` names what
    to bring in from `api.js` for it.
    """
    return run_module("""
      import { __IMPORTS__ } from './src/music_video_producer/web/assets/api.js';
      const TOKENS = __TOKENS__;
      const calls = [];
      const context = new Proxy({}, {
        get: (_bag, property) => (...args) => {
          calls.push({ call: String(property), args: args.map((value) => (
            typeof value === "number" ? Number(value.toFixed(4)) : value)) });
        },
        set: (_bag, property, value) => {
          calls.push({ set: String(property), value: String(value) });
          return true;
        },
      });
      const canvas = { width: 0, height: 0, getContext: () => context };
      globalThis.window = {
        devicePixelRatio: __DPR__,
        getComputedStyle: () => ({ getPropertyValue: (name) => (TOKENS[name] || "") }),
      };
      __SOURCE__
      const plan = __PLAN__;
      __NAME__(canvas, plan);
      console.log(JSON.stringify({ calls, plan, canvas }));
    """.replace("__IMPORTS__", imports)
       .replace("__TOKENS__", json.dumps(DRAWING_TOKENS))
       .replace("__DPR__", json.dumps(device_pixels))
       .replace("__SOURCE__", app_js_function(name))
       .replace("__PLAN__", plan)
       .replace("__NAME__", name))


def drawn(calls: list[dict], name: str) -> list[tuple[int, list]]:
    """Every `(index, args)` for one recorded context method, in the order it was called."""
    return [(index, item["args"]) for index, item in enumerate(calls) if item.get("call") == name]


def painted_with(calls: list[dict], index: int, property_name: str) -> str:
    """The value `property_name` last held before the call at `index` -- which token a stroke was
    actually drawn in, rather than which tokens appear somewhere in the log."""
    written = [item["value"] for item in calls[:index] if item.get("set") == property_name]
    return written[-1] if written else ""


# A stub DOM barely complete enough to boot `app.js` under node, so the workspace's own code can be
# *run* rather than read.
#
# Everything else in this file that concerns app.js reads its source, because a browser is not
# available -- and source reading has one hole this closes: a function can be perfectly correct, and
# asserted about in detail, while nothing ever calls it. `renderSongContext` is the case that
# matters. It is the only thing that seeds `#song-lyrics`/`#song-style` from the stored Song and the
# only thing that clears the `disabled` state the markup ships on both boxes and the save button; it
# is reached from exactly one line inside `renderSong`. Delete that line and the entire
# edit-after-import path is dead in every project, with every string assertion in this file still
# passing. So the render is executed here and the boxes are read afterwards.
#
# The stub creates an element for any selector asked for, records every listener bound to it, and
# records every request `fetch` is handed before rejecting it -- which is what makes "the guard
# stopped the switch" and "the save was never sent" observable. `window.confirm` throws until a test
# answers it, so an unexpected question is a failure rather than a silently accepted one.
WORKSPACE_HARNESS = """
const registry = new Map();
const listeners = new Map();
const requests = [];
//: The selector of the element `focus()` was last called on, or "".
let focused = "";
const make = (selector) => ({
  selector, value: "", disabled: false, checked: false, textContent: "", innerHTML: "",
  className: "", title: "", src: "", min: "", max: "", required: false,
  // The element's own id, and `contains`, which together are what make the focus-preserving
  // rebuild *observable*. `captureInspectorEdit` asks exactly two questions -- does the focused
  // element have an id, and is it inside this panel -- and with neither answerable here it
  // returned `null` for every element in every test, so "an in-progress edit survives the
  // two-second reload" was a guarantee nothing in this file could fail on.
  //
  // Neither changes anything that was passing: `document.activeElement` is undefined unless a test
  // sets it, which is the same deliberate separation the `focus()` note below describes.
  id: selector.startsWith("#") ? selector.slice(1) : "",
  contains(node) {
    return Boolean(node?.id) && String(this.innerHTML || "").includes('id="' + node.id + '"');
  },
  dataset: {}, style: {}, files: [],
  elements: new Proxy({}, { get: (bag, name) => (bag[name] ||= make(selector + "[" + String(name) + "]")) }),
  classList: {
    flags: new Set(),
    add(name) { this.flags.add(name); },
    remove(name) { this.flags.delete(name); },
    toggle(name, on) { if (on) this.flags.add(name); else this.flags.delete(name); },
    contains(name) { return this.flags.has(name); },
  },
  addEventListener(type, handler) { listeners.set(selector + ":" + type, handler); },
  // Focus is recorded rather than discarded, so "the focus follows the card" is a measurement.
  // Deliberately **not** wired to `document.activeElement`: that is what `captureInspectorEdit`
  // reads to decide there is an edit in progress, and making every focus call look like one
  // would change what the two-second rebuild restores under every test in this file.
  focus() { focused = this.selector; },
  append() {}, remove() {}, pause() {}, load() {}, click() {},
  // Attributes are recorded rather than discarded. They were no-ops, and that was a hole with a
  // shape: an accessible name is *only* ever set through `setAttribute`, so no test in this file
  // could read one back, and `aria-label` and `aria-pressed` were assertable only as authored
  // markup in `index.html` -- which is exactly the half the renderer overwrites. A control whose
  // name is composed at runtime could be bound to the wrong string and every test would pass.
  attributes: {},
  setAttribute(name, value) { this.attributes[name] = String(value); },
  removeAttribute(name) { delete this.attributes[name]; },
  getAttribute(name) { return name in this.attributes ? this.attributes[name] : null; },
  querySelectorAll: () => [],
  // A settable box, so geometry is a thing a test can arrange rather than one constant every
  // element shares. The drop target of a reorder drag is decided from measured card boxes, and
  // with one box for the whole document "the pointer is over the second card" is unstateable --
  // every card would answer to every pointer position and a wrong answer would look right.
  // `right` and `bottom` are derived rather than omitted: a real `DOMRect` always carries them,
  // and code reading `box.bottom` off this stub was reading `undefined`.
  rect: { left: 0, top: 0, width: 1000, height: 300 },
  getBoundingClientRect() {
    return {
      ...this.rect,
      right: this.rect.left + this.rect.width,
      bottom: this.rect.top + this.rect.height,
    };
  },
  closest() { return this; },
  // A minimal scoped `querySelector`, over the markup this element was just given. Id
  // selectors only, which is every scoped single-element lookup in app.js. It answered `null`
  // before, and that was the same hole `querySelectorAll` closed below: a control drawn into a
  // bar and then bound with `$("#id", bar)` was bound to nothing in this harness, so no test
  // could click one -- which is exactly how a two-stage report-then-confirm button would go
  // untested. Each match resolves to the registry's own element, so a test fires it by id.
  querySelector(selector) {
    if (!selector.startsWith("#")) return null;
    return String(this.innerHTML || "").includes('id="' + selector.slice(1) + '"')
      ? at(selector)
      : null;
  },
  // A minimal scoped `querySelectorAll`, over the markup this element was just given. Class
  // selectors only, which is every scoped use in app.js.
  //
  // It answered `[]` before, and that was a hole rather than a simplification: a handler bound with
  // `$$(".remove-ref", inspector)` was bound to nothing in this harness, so no test could reach one.
  // Per-citation controls are the case that made it matter -- a role select drawn once per cited
  // asset cannot be addressed by a fixed id, so the only way to execute one is to find it the way
  // the panel's own code does.
  //
  // Each match is registered under `<selector>[<data-id>]`, so a test fires it as
  // `.citation-role[asset_wolf]:change` and sets `.value` on the same element the handler reads.
  querySelectorAll(selector) {
    if (!selector.startsWith(".")) return [];
    const wanted = selector.slice(1);
    const found = [];
    for (const match of String(this.innerHTML || "").matchAll(/<(\\w+)\\s([^>]*?)>/g)) {
      const attributes = match[2];
      const classes = ((/class="([^"]*)"/.exec(attributes) || [null, ""])[1]).split(/\\s+/);
      if (!classes.includes(wanted)) continue;
      const id = (/data-id="([^"]*)"/.exec(attributes) || [null, ""])[1];
      const element = at(selector + "[" + id + "]");
      element.dataset.id = id;
      found.push(element);
    }
    return found;
  },
});
const at = (selector) => {
  if (!registry.has(selector)) registry.set(selector, make(selector));
  return registry.get(selector);
};
// The generation form is read at bind time by syncMusicVariant, which needs a real preset.
at("#music-form").elements.preset.value = "balanced";
globalThis.document = { querySelector: at, querySelectorAll: () => [], createElement: () => make("<created>") };
globalThis.window = {
  addEventListener(type, handler) { listeners.set("window:" + type, handler); },
  // Really removed, so a gesture that ends is a gesture nothing can fire again. Without it the
  // workspace's own `window.removeEventListener` -- every pointer drag in `app.js` releases its
  // move and up listeners that way -- was a `TypeError` the moment a drag was driven here.
  removeEventListener(type) { listeners.delete("window:" + type); },
  confirm: (question) => { throw new Error("unanswered confirm: " + question); },
  prompt: () => null,
};
// Canned answers keyed by exact path, for the tests that need the workspace to *receive*
// something rather than only to be watched sending. `__RESPONSES__` is `{}` for every existing
// caller, so an unlisted path rejects exactly as it always did and nothing already written here
// changes behaviour. Each entry is `{body}` for a 200, or `{status, body}` to be refused.
//
// **Or a list of those, answered in order, the last one repeating.** One path answering one body
// for the life of a test cannot express a measurement being taken: `timeline/snap-targets` is read
// on the load path saying `analysed: false` and read again after the analysis saying `analysed:
// true`, and with a single body "it asked again" and "the answer changed" collapse into one
// another -- a test would pass just as happily against a client that re-read nothing. A plain
// object is still a plain object, so nothing already written here is affected.
//
// **`unconsumed()` is what stops that guarantee going vacuous.** A list whose later entries are
// never asked for leaves the test asserting about the first answer only, and passing -- which is
// exactly the client that re-read nothing. A test that means "and it asked again" asserts the
// leftovers are empty. An *exhausted* list is a named refusal rather than a `TypeError` about
// reading a property of `undefined`, because a harness failure that reads like a code failure
// costs the next reader the same twenty minutes every time.
const responses = new Map(Object.entries(__RESPONSES__));
const unconsumed = () => Object.fromEntries(
  [...responses.entries()]
    .filter(([, listed]) => Array.isArray(listed) && listed.length > 1)
    .map(([path, listed]) => [path, listed.length - 1])
);
globalThis.fetch = (path, options = {}) => {
  requests.push({ path, method: options.method || "GET", body: options.body || null });
  if (!responses.has(path)) return Promise.reject(new Error("the contract harness makes no requests"));
  const listed = responses.get(path);
  if (Array.isArray(listed) && listed.length === 0) {
    return Promise.reject(new Error("the canned replies for " + path + " are exhausted"));
  }
  const canned = Array.isArray(listed)
    ? (listed.length > 1 ? listed.shift() : listed[0])
    : listed;
  const status = canned.status || 200;
  return Promise.resolve({
    ok: status < 400,
    status,
    statusText: "canned",
    headers: { get: () => "application/json" },
    json: async () => canned.body,
  });
};
// The browser session store, `mvp-session`, seeded with `__SESSION__` before the workspace boots.
// It answered `undefined` before, which every reader here catches -- so `persistSession` threw and
// was swallowed, and `restoreSession` returned `{}`: a stored view setting could be neither written
// nor read back by any test. Seeded, the two halves of "it survives a reload" become executable,
// which is the only way to tell a setting that persists from one that is merely spelled correctly.
const storage = new Map(Object.entries(__SESSION__));
globalThis.localStorage = {
  getItem: (key) => (storage.has(key) ? storage.get(key) : null),
  setItem: (key, value) => { storage.set(key, String(value)); },
  removeItem: (key) => { storage.delete(key); },
};
// The workspace boots on import: it binds every handler, then fires its startup requests, which
// reject. Timers are stubbed out so a pending toast cannot hold the process open for its 4.2 s.
globalThis.setTimeout = () => 0;
globalThis.setInterval = () => 0;
globalThis.requestAnimationFrame = () => 0;
const app = await import('./src/music_video_producer/web/assets/app.js');
const contract = await import('./src/music_video_producer/web/assets/api.js');
const { state } = await import('./src/music_video_producer/web/assets/state.js');
const fire = (key, event = {}) => {
  const handler = listeners.get(key);
  if (!handler) throw new Error("nothing is bound to " + key);
  return handler(event);
};
let asked = [];
const answer = (reply) => {
  asked = [];
  requests.length = 0;
  globalThis.window.confirm = (question) => { asked.push(question); return reply; };
};
// The workspace's startup requests are fired but not awaited by the module's top level, so a test
// that asserts about what a *reply* did to the DOM has to let those promises settle first. Real
// promises, so draining the microtask queue is enough -- and `setTimeout` is stubbed out, so
// waiting on a timer would hang instead.
const flush = async () => { for (let index = 0; index < 60; index += 1) await Promise.resolve(); };
"""


def run_workspace(body: str, responses: dict | None = None, session: dict | None = None):
    """Boot `app.js` against the stub DOM and run `body` against the workspace it produced.

    `responses` maps an exact request path to `{"body": ...}` for a 200, or
    `{"status": N, "body": ...}` for a refusal. Anything unlisted is rejected, which is what
    every caller that passes nothing gets. A *list* of those is answered in order, with the last
    entry repeating -- which is how one path answers differently before and after a measurement.
    The workspace body can call `unconsumed()` for the entries no request ever reached, so a test
    that means "and it asked again" can assert that rather than assume it.

    `session` seeds `localStorage` *before* the workspace boots, keyed by storage key -- so
    `{"mvp-session": json.dumps({...})}` is what a Director's browser carries into a reload. The
    default is an empty store, which is a first-ever visit and is what every existing caller gets.
    """
    harness = WORKSPACE_HARNESS.replace("__RESPONSES__", json.dumps(responses or {}))
    harness = harness.replace("__SESSION__", json.dumps(session or {}))
    return run_module(harness + body)


def document_controls() -> dict:
    """api.js's one table of per-document selectors, project fields and document tab."""
