def test_the_queue_column_shows_the_caveat_rather_than_hiding_it_in_a_tooltip():
    """`≤` is the caveat made visible: an enqueue-to-settle span is an upper bound on the
    render and never the render itself, and a reader scanning the column has to see that
    without hovering. The full sentence rides the same cell's `title`.

    The two bare `record`-sourced cells are the finished export: local work that was never in a
    queue, so its span is the whole job and a `≤` would claim a wait that cannot have happened.
    The crashed one keeps the mark, because that span runs to the next boot."""
    jobs = [json.loads(RenderJob(**fields).model_dump_json()) for fields in TIMING_JOBS]
    body = f"""
      console.log(JSON.stringify({json.dumps(jobs)}.map(app.renderTimingCell)));
    """

    cells = run_workspace(body)

    assert cells == ["6m18s · 141f", "≤30m12s · 226f", "≤1m35s", "≤40m00s · 141f",
                     "≤1h01m · 277f", "3m12s · 141f", "6m18s", "≤9h00m", "—", "—"]
    # Nothing measured by ComfyUI's own clock is marked as an upper bound -- a failure it timed
    # included, which is the row that used to disagree with the column header above it.
    assert not cells[0].startswith("≤")
    assert not cells[5].startswith("≤")
    # A settle with no length draws no number at all: `0s` would be a claim about a render.
    assert cells[8] == "—"


def test_the_queue_panel_actually_draws_the_column_it_declares():
    """A header with no cell under it, or a cell with no header over it, is a table that lies
    about which column a number is in. Both sides are read, and so is the grid that lays them
    out -- a six-column header over a five-column grid template silently overflows."""
    header = re.search(r'<div class="queue-header">(.*?)</div>', INDEX_HTML.read_text("utf-8"))
    assert header, "the queue table no longer declares a header row"
    columns = re.findall(r"<span[^>]*>([^<]+)</span>", header.group(1))
    assert columns == ["Job", "Target", "Status", "Seed", "Took", "Bundle", "Output"]

    source = without_comments(APP_JS.read_text(encoding="utf-8"))
    row = source.split('list.innerHTML = progress +', 1)[1].split("\n", 1)[0]
    assert 'class="job-took"' in row, "the queue row draws no timing cell under the Took header"
    assert "renderTimingCell(job)" in row
    assert "renderTimingSummary(job)" in row, "the full sentence must ride the cell's title"
    # Bundle sits beside Took, and in that order: the two are read together, because a duration
    # means one thing at 20 steps and another at 8.
    assert 'class="job-bundle"' in row, "the queue row draws no cell under the Bundle header"
    assert "samplingBundleCell(job)" in row
    assert "samplingBundleSummary(job)" in row, "the full sentence must ride the cell's title"
    assert row.index('class="job-took"') < row.index('class="job-bundle"')

    grid = re.search(
        r"\.queue-header, \.job-row \{[^}]*grid-template-columns: ([^;]+);",
        STYLES_CSS.read_text(encoding="utf-8"),
    )
    assert grid, "the queue grid no longer declares its columns"
    assert len(grid.group(1).split()) == len(columns)


# ----------------------------------------------------------------------------------------------
# Which bundle produced which take, surfaced (2026-08-23).
#
# The bundle became a per-project choice, so a project's takes are a mixture. The record is only
# worth taking if a Director can read it beside the duration it explains — 6m18s means one thing at
# twenty steps and another at eight — and it is only *honest* if a job that predates the field
# reads as unknown rather than as a bundle it may never have run.
#
# So the sentence is written once, in `batch.sampling_bundle_summary`, and the browser's copy is
# executed under node against the same jobs and compared character for character, exactly as the
# timing sentence above it is.
# ----------------------------------------------------------------------------------------------

#: Every branch of `sampling_bundle_summary` and of `sampling_bundle_cell`, in one table.
BUNDLE_JOBS = [
    # The default bundle, applied: no LoRA, and the sentence must say so rather than trailing off.
    {"kind": "h3", "sampling_bundle": {
        "name": "default", "steps": 20, "sampler": "res_multistep", "scheduler": "simple",
        "lora": "", "lora_strength": 0.0}},
    # The two turbo bundles, each with its own LoRA at its own strength. `1.0` and `0.7` are the
    # two spellings that made a shared formatter necessary: Python's `str(1.0)` is `1.0` and
    # JavaScript's is `1`.
    {"kind": "h3", "sampling_bundle": {
        "name": "turbo", "steps": 4, "sampler": "euler", "scheduler": "beta",
        "lora": "minimax_h3_ref2v_turbo_4step_v0.1_comfyui_bf16.safetensors",
        "lora_strength": 0.7}},
    {"kind": "h3", "sampling_bundle": {
        "name": "turbo-references2v", "steps": 8, "sampler": "euler", "scheduler": "simple",
        "lora": "minimax_h3_turbo_v4_step600_ema_pruned_comfyui.safetensors",
        "lora_strength": 1.0}},
    # A bundle whose step count the request overrode: the case a name-only record gets wrong.
    {"kind": "h3", "sampling_bundle": {
        "name": "turbo", "steps": 12, "sampler": "euler", "scheduler": "beta",
        "lora": "minimax_h3_ref2v_turbo_4step_v0.1_comfyui_bf16.safetensors",
        "lora_strength": 0.7}},
    # An H3 graph that has no evidenced bundle: the keyframe and text-only paths. Not unknown.
    {"kind": "h3", "sampling_bundle": {"name": "none"}},
    # Every H3 job written before 2026-08-23: no record, and none invented.
    {"kind": "h3"},
    # And the kinds that submit no H3 graph at all, which `kind` answers without any record.
    {"kind": "post"},
    {"kind": "flux"},
    {"kind": "ltx", "sampling_bundle": {"name": "turbo", "steps": 4}},
]


def test_the_browsers_bundle_sentence_is_the_servers_sentence_character_for_character():
    jobs = [RenderJob(target_id="shot_a", **fields) for fields in BUNDLE_JOBS]
    wire = json.dumps([json.loads(job.model_dump_json()) for job in jobs])
    body = f"""
      console.log(JSON.stringify({wire}.map(app.samplingBundleSummary)));
    """

    assert run_workspace(body) == [sampling_bundle_summary(job) for job in jobs]


def test_the_two_lora_strength_formatters_agree():
    """`str(1.0)` is `1.0` in Python and `1` in JavaScript, and the sentence carrying the value is
    compared character for character. The range is `H3_LORA_STRENGTH_LIMITS`, plus the negative
    and non-finite values a hand-edited manifest can hold."""
    table = [0, 0.7, 1.0, 1.5, -1.5, 12.25, 100.0, -100.0, 0.05,
             # A hand-edited manifest can hold these and Pydantic accepts them on a `float`.
             # `%g` would print `inf`/`nan` and `String()` would print `Infinity`/`NaN`, so both
             # sides refuse to render a strength that is not one — the em dash `format_duration`
             # already draws for the same reason.
             float("inf"), float("-inf"), float("nan")]
    body = f"""
      console.log(JSON.stringify({json.dumps(table)}.map(app.formatLoraStrength)));
    """

    rendered = run_workspace(body)

    assert rendered == [format_lora_strength(value) for value in table]
    assert rendered[-3:] == ["—", "—", "—"]


def test_the_bundle_column_names_the_bundle_and_marks_an_unrecorded_one_as_unknown():
    """The terse form, and the one requirement the column was added under: an unknown bundle is
    visibly unknown rather than blank-and-ambiguous.

    `—` is what a job with no H3 graph draws — a known negative that needs no record. A job whose
    bundle nobody recorded reads as a word, so a Director scanning the column tells the two apart
    without hovering and without supplying the answer themselves.

    The steps ride the cell because they are the number a *name alone* gets wrong: rows two and
    four are the same bundle at four steps and at twelve.
    """
    jobs = [json.loads(RenderJob(**fields).model_dump_json()) for fields in BUNDLE_JOBS]
    body = f"""
      console.log(JSON.stringify({json.dumps(jobs)}.map(app.samplingBundleCell)));
    """

    cells = run_workspace(body)

    assert cells == ["default · 20", "turbo · 4", "turbo-references2v · 8", "turbo · 12",
                     "none", "unknown", "—", "—", "—"]
    assert cells == [sampling_bundle_cell(RenderJob(**fields)) for fields in BUNDLE_JOBS]
    # The three that are not a bundle name are three different statements and no two of them
    # may collapse into one another.
    assert len({cells[4], cells[5], cells[6]}) == 3


def test_no_surface_ever_reads_an_unrecorded_bundle_as_the_default_one():
    """The constraint that matters most, asserted as an absence on both sides.

    An old job carries no bundle, and every sentence and cell about it must say *unknown*. The
    failure this pins is not a crash — it is a job silently drawn as `default · 20`, which is a
    fabricated measurement quoted onward as evidence, and is the exact shape this application
    spent two days retiring.
    """
    unrecorded = RenderJob(kind="h3", target_id="shot_a")

    assert unrecorded.sampling_bundle is None
    assert sampling_bundle_cell(unrecorded) == "unknown"
    for text in (sampling_bundle_cell(unrecorded), sampling_bundle_summary(unrecorded)):
        assert "default" not in text
        # No step count either, in cell form or in sentence form. The date it names contains
        # "20" and is not a claim about sampling, so the two spellings are excluded by name.
        assert "· 20" not in text
        assert "20 steps" not in text
    # And the browser agrees, from the same record, through its own two functions.
    wire = json.dumps(json.loads(unrecorded.model_dump_json()))
    verdict = run_workspace(f"""
      console.log(JSON.stringify({{
        cell: app.samplingBundleCell({wire}),
        sentence: app.samplingBundleSummary({wire}),
      }}));
    """)
    assert verdict["cell"] == "unknown"
    assert verdict["sentence"] == sampling_bundle_summary(unrecorded)


# --- The sampling bundle control -------------------------------------------------------------
#
# The Director's ruling of 2026-08-23 made the bundle a visible choice: turbo is "almost sweaty"
# but "both still look good so up to user". What these pin is the defect the ruling was the
# occasion to fix -- `api.generateBatch` sent no profile and got 20 steps while "Render Again"
# hardcoded `turbo` and got 4, and nothing on screen named either number.
#
# Every decision here is *executed* rather than read out of the source. A control can be perfectly
# described in a comment and bound to nothing, and a select that writes the wrong project or sends
# the wrong body is exactly the failure a source read cannot see.


def test_the_bundle_select_offers_the_three_bundles_the_route_accepts():
    """The select's options and the server's `Literal` must not drift apart.

    A bundle offered here that the route does not know is a 422 the Director cannot avoid; one the
    route accepts and this does not offer is unreachable, which is the whole point of the control.
    The step count is asserted to be in the option's own visible text rather than in a tooltip:
    "8 steps" is the information the ruling turns on, and a Director choosing a look must not have
    to hover to find out what it costs.
    """
    from music_video_producer.models import SamplingProfile
    from music_video_producer.workflows import H3_REFERENCE_PROFILES

    offered = run_module("""
      import { SAMPLING_PROFILES, samplingProfileOf, samplingProfileSpec }
        from './src/music_video_producer/web/assets/api.js';
      console.log(JSON.stringify({
        profiles: SAMPLING_PROFILES,
        unknownStored: samplingProfileOf({ sampling_profile: 'fast' }),
        missingStored: samplingProfileOf({}),
        noProject: samplingProfileOf(null),
        knownStored: samplingProfileOf({ sampling_profile: 'turbo' }),
        unknownSpec: samplingProfileSpec('fast').value,
      }));
    """)

    values = [entry["value"] for entry in offered["profiles"]]
    assert set(values) == set(get_args(SamplingProfile)) == set(H3_REFERENCE_PROFILES)
    # Offered default-first, so the option the Director lands on with no choice made is the one
    # that renders exactly as this application always has.
    assert values[0] == "default"
    for entry in offered["profiles"]:
        assert entry["steps"] == H3_REFERENCE_PROFILES[entry["value"]].steps
        assert f"{entry['steps']} steps" in entry["label"], entry

    # A stored name this build does not know draws as the default rather than as a blank select or
    # an invented option: stale storage may cost a default, never a wrong state on screen.
    assert offered["unknownStored"] == "default"
    assert offered["missingStored"] == "default"
    assert offered["noProject"] == "default"
    assert offered["knownStored"] == "turbo"
    assert offered["unknownSpec"] == "default"


def test_the_comparisons_findings_sit_under_the_control_that_acts_on_them():
    """The four things the 2026-08-23 comparison actually found, where the choice is made.

    Including the one that reports an *absence*. No hands were in frame in any of the six renders,
    so a Director reading "sharper, waxier skin" and inferring anything about hands would be
    inferring it from nothing -- and that is the belief a findings note has to stop rather than the
    result it reports.
    """
    note = run_module("""
      import { SAMPLING_PROFILE_NOTE_TEXT, SAMPLING_PROFILE_TITLE }
        from './src/music_video_producer/web/assets/api.js';
      console.log(JSON.stringify({
        note: SAMPLING_PROFILE_NOTE_TEXT, title: SAMPLING_PROFILE_TITLE,
      }));
    """)

    text = note["note"]
    # Lip-sync: indistinguishable, with the numbers rather than the adjective alone.
    assert "lip-sync is indistinguishable" in text
    assert "within 0.005" in text and "0.1 ms" in text
    # Picture: sharper, not softer -- the correction that matters, and its cost.
    assert "sharper rather than softer" in text
    assert "+52% to +152%" in text
    assert "waxier" in text
    # The saving, and where it comes from.
    assert "~2.0" in text
    assert "step count, not from per-step speed" in text
    # The absence.
    assert "hands are untested" in text
    # Short enough to be read where it sits, which is the difference between a note and an essay.
    assert len(text) < 600, len(text)

    # The scope belongs to the hover text, not the note: it is a standing limit of the field
    # rather than a finding, and it is the clause that stops "I chose turbo" being read as "every
    # shot renders on turbo".
    assert "Reference shots only" in note["title"]
    assert "always render at 20 steps" in note["title"]
    assert "Render Again" in note["title"] and "Generate All" in note["title"]


def test_the_batch_estimate_names_the_chosen_bundle_and_invents_no_figure():
    """The queue line said "~2.7 min on turbo" for every batch, and the batch never used turbo.

    That is worse than a stale number: it attributed every render to a bundle
    `api.generateBatch` had never sent, because it sent no profile at all and got the 20-step
    default. The replacement quotes a measured figure where one exists and says nothing where one
    does not -- the 4-step bundle was not in the 2026-08-23 comparison, so no minutes are
    interpolated for it from a step ratio.
    """
    notes = run_module("""
      import { batchEtaNote } from './src/music_video_producer/web/assets/api.js';
      console.log(JSON.stringify({
        def: batchEtaNote('default', 6),
        turbo2v: batchEtaNote('turbo-references2v', 6),
        turbo: batchEtaNote('turbo', 6),
        unknown: batchEtaNote('fast', 6),
        none: batchEtaNote('default', 0),
      }));
    """)

    assert notes["def"] == " (~48 min on Default)"
    assert notes["turbo2v"] == " (~24 min on Turbo References2V)"
    # Measured on nothing, so it says nothing rather than guessing 6 x 2.7.
    assert notes["turbo"] == ""
    # An unrecognised name falls to the default's row rather than to a blank or a crash.
    assert notes["unknown"] == " (~48 min on Default)"
    assert notes["none"] == ""


def test_the_generate_all_confirmation_names_the_bundle_it_would_spend():
    """The last moment before hours of GPU, and until now it named no bundle at all.

    The default's own cost sentence is asserted word for word: a Director who has touched nothing
    must read exactly what they read before this control existed, which is the same promise the
    payload digest makes on the other side of the wire.
    """
    plans = run_module("""
      import { generateAllPlan } from './src/music_video_producer/web/assets/api.js';
      const shots = [{ id: 'shot_a', status: 'ready' }, { id: 'shot_b', status: 'ready' }];
      console.log(JSON.stringify({
        untouched: generateAllPlan({ shots }, null),
        turbo2v: generateAllPlan({ shots, sampling_profile: 'turbo-references2v' }, null),
        turbo: generateAllPlan({ shots, sampling_profile: 'turbo' }, null),
      }));
    """)

    assert "Bundle: Default — 20 steps." in plans["untouched"]["confirm"]
    assert (
        "A reference shot measured 288-438 s on the default profile."
        in plans["untouched"]["confirm"]
    )
    assert "Bundle: Turbo References2V — 8 steps." in plans["turbo2v"]["confirm"]
    assert "2.0× faster than default" in plans["turbo2v"]["confirm"]
    assert "Bundle: Turbo LTX LoRA — 4 steps." in plans["turbo"]["confirm"]
    assert "not measured" in plans["turbo"]["confirm"]
    # The button's own title stays about what would queue. The select beside it carries the
    # bundle, and a second copy in a tooltip is a second thing to keep true.
    assert plans["turbo"]["title"] == "Generate 2 H3 shots"


def test_the_bundle_select_writes_the_project_and_repaints_from_the_reply():
    """The control, executed: it sends the select's own value to the one route that writes it.

    Three things a source read cannot see, and each has been a real defect in this workspace: that
    the handler is bound at all; that it sends the *select's* value rather than a hardcoded one;
    and that a refused change reverts the control instead of leaving it showing a bundle no render
    will honour.
    """
    driven = run_workspace(
        """
      state.project = { id: 'p1', name: 'Third Video', shots: [], jobs: [],
        sampling_profile: 'default' };
      app.renderJobs();
      const drawn = {
        options: at('#sampling-profile').innerHTML,
        value: at('#sampling-profile').value,
        note: at('#sampling-profile-note').textContent,
        title: at('#sampling-profile').title,
      };
      // The Director picks the 8-step bundle.
      at('#sampling-profile').value = 'turbo-references2v';
      requests.length = 0;
      await fire('#sampling-profile:change', { currentTarget: at('#sampling-profile') });
      const accepted = {
        sent: [...requests],
        stored: state.project.sampling_profile,
        value: at('#sampling-profile').value,
      };
      // And a refusal: the select must go back to what the server still holds.
      at('#sampling-profile').value = 'turbo';
      requests.length = 0;
      await fire('#sampling-profile:change', { currentTarget: at('#sampling-profile') });
      const refused = {
        sent: requests.length,
        stored: state.project.sampling_profile,
        value: at('#sampling-profile').value,
      };
      console.log(JSON.stringify({ drawn, accepted, refused,
        toast: contract.samplingProfileToast('turbo-references2v') }));
    """,
        {
            "/api/projects/p1/sampling-profile": {
                "body": {
                    "id": "p1", "name": "Third Video", "shots": [], "jobs": [],
                    "sampling_profile": "turbo-references2v",
                }
            }
        },
    )

    # Drawn from the stored project: three options, the stored one selected, the findings under it.
    assert driven["drawn"]["options"].count("<option") == 3
    assert 'value="turbo-references2v"' in driven["drawn"]["options"]
    assert driven["drawn"]["value"] == "default"
    assert "hands are untested" in driven["drawn"]["note"]
    assert "Reference shots only" in driven["drawn"]["title"]

    # Accepted: one PUT, to the narrow route, carrying the select's own value -- and the state
    # adopts the server's reply, so the confirmation Generate All shows is the stored bundle.
    assert len(driven["accepted"]["sent"]) == 1
    sent = driven["accepted"]["sent"][0]
    assert sent["method"] == "PUT"
    assert sent["path"] == "/api/projects/p1/sampling-profile"
    assert json.loads(sent["body"]) == {"profile": "turbo-references2v"}
    assert driven["accepted"]["stored"] == "turbo-references2v"
    assert driven["accepted"]["value"] == "turbo-references2v"

    # Refused (the harness rejects any unlisted path): the attempt was made, and the select is
    # repainted from what the server still holds rather than left showing the Director's click.
    assert driven["refused"]["sent"] == 1
    assert driven["refused"]["stored"] == "turbo-references2v"
    assert driven["refused"]["value"] == "turbo-references2v"

    assert "Render Again" in driven["toast"] and "Generate All" in driven["toast"]


def test_neither_render_path_sends_a_hardcoded_bundle_any_more():
    """The defect itself, pinned from both ends so it cannot come back on either.

    The batch button is *executed* -- the request it produces is read off the wire -- because that
    is the half where "sends no profile" is a claim about bytes. "Render Again" is bound per
    rendered shot rather than once at boot, so its body is asserted from the source; what makes
    that assertion sound is that the literal it used to carry appears nowhere in the file.
    """
    driven = run_workspace(
        """
      state.project = { id: 'p1', name: 'Third Video', sampling_profile: 'turbo-references2v',
        shots: [{ id: 'shot_a', status: 'ready', prompt: 'A singer', start: 0, duration: 5 }],
        jobs: [] };
      app.renderJobs();
      answer(true);
      requests.length = 0;
      await fire('#queue-ready:click', {});
      console.log(JSON.stringify({ asked: [...asked], sent: [...requests] }));
    """,
        {
            "/api/projects/p1/generate/batch": {
                "body": {"batch_id": "batch_1", "submitted": [], "skipped": []}
            }
        },
    )

    # The confirmation names the bundle the batch is about to spend.
    assert len(driven["asked"]) == 1
    assert "Bundle: Turbo References2V — 8 steps." in driven["asked"][0]

    batch = next(sent for sent in driven["sent"] if sent["path"].endswith("/generate/batch"))
    body = json.loads(batch["body"])
    # No profile on the wire: the server resolves it from the project, which is what makes this
    # button and Render Again incapable of disagreeing.
    assert "profile" not in body, body
    assert body["confirm_gpu"] is True

    source = APP_JS.read_text(encoding="utf-8")
    assert "api.generateH3(projectId, shot.id, {})" in source
    # The two hardcoded spellings that produced the split, gone from the render paths entirely.
    assert 'profile: "turbo"' not in without_comments(source)
    assert '{ confirm_gpu: true, scope: "flagged" }' in source


def test_the_bundle_control_exists_in_the_queue_panel_and_hardcodes_no_option():
    """Where the control is, and the one thing its markup must *not* carry.

    The select ships **empty**. Its options are written by `renderSamplingProfile` from api.js's
    `SAMPLING_PROFILES`, so the three names offered are the three the route's `Literal` accepts and
    a bundle cannot be added on one side only — an `<option>` in the markup would be a second list
    to keep true, and the one that drifts. The findings note ships empty for the same reason: a
    hardcoded fallback sentence would be a second copy of the comparison's results.

    In the render-queue panel, beside Generate All, and **not** in the system state where the VRAM
    eject sits. That placement is the decision: the eject is a property of the machine, a bundle is
    a property of this project's look, so it belongs where the batch it governs is launched.
    """
    markup = INDEX_HTML.read_text(encoding="utf-8")
    exports = run_module("""
      import { SAMPLING_PROFILE_CONTROL, SAMPLING_PROFILE_LABEL, SAMPLING_PROFILE_NOTE }
        from './src/music_video_producer/web/assets/api.js';
      console.log(JSON.stringify({
        control: SAMPLING_PROFILE_CONTROL, label: SAMPLING_PROFILE_LABEL,
        note: SAMPLING_PROFILE_NOTE,
      }));
    """)

    control = re.search(r'<label class="replace-existing-line" id="sampling-profile-line".*?</label>', markup)
    assert control, "the render queue no longer carries the bundle control"
    assert 'id="{}"'.format(exports["control"].removeprefix("#")) in control.group(0)
    assert exports["label"] in control.group(0), exports["label"]
    # Empty on both counts, so neither list nor sentence exists twice.
    assert "<option" not in control.group(0), control.group(0)
    note_id = exports["note"].removeprefix("#")
    assert f'id="{note_id}"></div>' in markup, "the findings note ships with a hardcoded sentence"

    panel = re.search(r'<section class="panel" id="panel-queue".*?</section>', markup, re.DOTALL)
    assert panel and f'id="{note_id}"' in panel.group(0)
    assert 'id="sampling-profile"' in panel.group(0)
    # Beside the batch button it governs, in the same actions row.
    actions = re.search(r'<div class="heading-actions">.*?id="queue-ready".*?</div>', panel.group(0), re.DOTALL)
    assert actions and 'id="sampling-profile"' in actions.group(0)

    styles = STYLES_CSS.read_text(encoding="utf-8")
    assert re.search(r"\.sampling-profile-note \{", styles), "the findings note has no style"


# ----------------------------------------------------------------------------------------------
# The failed-and-empty shot, the whole-queue cancel, and the timeline's render-phase indicator --
# the Director's three reports of 2026-08-23, after a Generate All they cancelled from ComfyUI's
# own UI because cancelling twenty-six renders in this application meant twenty-six clicks.
# ----------------------------------------------------------------------------------------------


def test_a_released_shot_offers_the_commit_control_and_a_settled_one_offers_the_flag():
    """Item 1's client half, executed: which control the inspector actually draws.

    The Director's report: after twenty-six failed renders "thier option is 'Flag for re-render'
    instead of just returning to ready after the fail". `Flag for re-render` is drawn on exactly
    the shots `renderAgainControl` is shown for, which is the settled set -- so releasing a
    takeless shot to `ready` is what takes the flag away, and nothing in the inspector needed a
    new rule. The two states are rendered here rather than reasoned about, because the flag rides
    `again.shown` and a template that had stopped reading it would still pass a source grep.
    """
    drawn = run_workspace("""
      const shot = (fields) => ({
        id: 'shot_a', start: 0, duration: 5, prompt: 'A singer turns toward camera',
        mode: 'text', asset_ids: [], reference_labels: {}, use_song_audio: false, seed: 0,
        status: 'ready', prompt_id: '', latest_output: '', approved_output: '', locked: false,
        flagged: false, ...fields,
      });
      const draw = (fields) => {
        state.project = { id: 'p1', assets: [], jobs: [], song: null, shots: [shot(fields)] };
        state.selectedShotId = 'shot_a';
        app.renderShotInspector();
        const html = at('#shot-inspector').innerHTML;
        return {
          flag: html.includes('id="flag-shot"'),
          again: html.includes('id="render-again"'),
          mark: html.includes('id="mark-ready"'),
          markLabel: (/id="mark-ready"[^>]*>([^<]*)</.exec(html) || [null, ''])[1],
        };
      };
      console.log(JSON.stringify({
        released: draw({}),
        settled: draw({ status: 'error', latest_output: 'takes/one.mp4' }),
      }));
    """)

    # A render that produced nothing leaves the shot armed: no take, so no flag and no re-open --
    # the only thing left to say about it is that it may be taken back out of the queue.
    assert drawn["released"] == {
        "flag": False, "again": False, "mark": True, "markLabel": "Back to draft",
    }
    # A failed re-render over a take it still holds is a settled shot, and both controls stand.
    assert drawn["settled"]["flag"] is True
    assert drawn["settled"]["again"] is True
    assert drawn["settled"]["mark"] is False


def test_the_release_rule_is_the_servers_and_the_client_never_re_derives_it():
    """The client draws `Back to draft` for a released shot because the *server* released it.

    Asserted as the server's own function over the same two shots the browser would be handed, so
    the two halves cannot come apart: nothing in `api.js` decides where a failed render leaves a
    shot, and nothing should -- `shot_status_after_failed_render` is the one implementation and
    `markReadyControl`/`renderAgainControl` only read the status it wrote.
    """
    from music_video_producer.batch import shot_status_after_failed_render

    takeless = Shot(id="s1", start=0, duration=4, prompt="Wide", status="queued")
    retake = Shot(id="s2", start=4, duration=4, prompt="Wide", status="running",
                  latest_output="takes/one.mp4")

    assert shot_status_after_failed_render(takeless) == "ready"
    assert shot_status_after_failed_render(retake) == "error"
    # And the two statuses land in the two halves of the client's control vocabulary, which is
    # what makes the inspector draw a different control for each without knowing why.
    controls = run_module("""
      import { MARK_READY_STATUSES, RENDER_AGAIN_STATUSES }
        from './src/music_video_producer/web/assets/api.js';
      console.log(JSON.stringify({ mark: MARK_READY_STATUSES, again: RENDER_AGAIN_STATUSES }));
    """)
    assert "ready" in controls["mark"] and "ready" not in controls["again"]
    assert "error" in controls["again"] and "error" not in controls["mark"]


def test_the_cancel_all_plan_counts_open_renders_and_names_the_count_before_it_fires():
    """Item 2's decision, executed for every state, and the confirmation pinned by its content.

    The count is the whole safety of the gesture: cancelling twenty-six renders is not undoable,
    and a dialog that did not say twenty-six would be a dialog nobody could judge. It is asserted
    as a substring of the sentence rather than against a constant the sentence was built from --
    `assert count in confirm` where `confirm` was formatted from `count` can only pass.
    """
    plans = run_module("""
      import { CANCEL_ALL_CONTROL, CANCEL_ALL_HELP, CANCEL_ALL_LABEL, cancelAllPlan }
        from './src/music_video_producer/web/assets/api.js';
      const job = (fields) => ({ id: 'j', kind: 'h3', status: 'queued', prompt_id: 'p', ...fields });
      console.log(JSON.stringify({
        control: CANCEL_ALL_CONTROL, label: CANCEL_ALL_LABEL, help: CANCEL_ALL_HELP,
        idle: cancelAllPlan({ jobs: [] }),
        settled: cancelAllPlan({ jobs: [job({ status: 'complete' }), job({ status: 'cancelled' })] }),
        local: cancelAllPlan({ jobs: [job({ kind: 'post', prompt_id: '' })] }),
        one: cancelAllPlan({ jobs: [job({ id: 'j1' })] }),
        many: cancelAllPlan({
          jobs: [job({ id: 'j1' }), job({ id: 'j2', status: 'running' }), job({ id: 'j3', kind: 'music' })],
        }),
        missing: cancelAllPlan(null),
      }));
    """)

    # Nothing open, in four different ways, and every one of them hides the button rather than
    # disabling it: "nothing is rendering" is not a refusal that needs explaining.
    for quiet in ("idle", "settled", "local", "missing"):
        assert plans[quiet]["count"] == 0, quiet
        assert plans[quiet]["hidden"] is True, quiet
        assert plans[quiet]["confirm"] == "", quiet
    # A local export (empty prompt_id) is deliberately out of scope: nothing here could stop a
    # running ffmpeg, so settling its record would be a claim the button cannot back.
    assert plans["local"]["count"] == 0

    assert plans["one"]["count"] == 1
    assert plans["one"]["hidden"] is False
    assert plans["one"]["label"] == "Cancel all renders (1)"
    assert "Cancel 1 open render for this project?" in plans["one"]["confirm"]
    # Singular, not "1 open renders".
    assert "1 open renders" not in plans["one"]["confirm"]

    # Every open ComfyUI job, whatever its kind and whatever batch it belongs to -- the scope
    # argument in `app.CANCEL_ALL_NONE_OPEN`'s note, executed.
    assert plans["many"]["count"] == 3
    assert plans["many"]["label"] == "Cancel all renders (3)"
    confirm = plans["many"]["confirm"]
    assert "Cancel 3 open renders for this project?" in confirm
    # Pinned by content, so a dialog that stopped saying what it costs fails here. Each clause is
    # a separate fact the Director acts on: the scope is wider than the batch line above the
    # button, the act cannot be undone, and the shots come back.
    assert "not just the newest batch" in confirm
    assert "cannot be undone" in confirm
    assert "go back to ready" in confirm
    assert plans["control"] == "#queue-cancel-all"
    assert "not just the newest batch" in plans["help"]


def test_the_cancel_all_button_is_drawn_confirmed_and_sent_against_the_real_workspace():
    """The button, rendered, refused once and then clicked -- never grepped.

    Three things no source read can establish. The queue panel really applies `cancelAllPlan`
    (a panel that drew the button for an idle project would fail here); declining the dialog
    really sends nothing, which is the whole point of a confirmation on an act that cannot be
    undone; and the click reaches the collection route with the acknowledgement on it rather than
    looping the per-job `DELETE` from the browser, which would be a second cancellation path.
    """
    driven = run_workspace(
        """
      const job = (fields) => ({
        id: 'j1', kind: 'h3', batch_id: 'batch_1', status: 'queued', prompt_id: 'p1',
        target_id: 'shot_a', seed: 0, output_files: [], error: '', ...fields,
      });
      state.project = {
        id: 'p1', assets: [], jobs: [job({}), job({ id: 'j2', prompt_id: 'p2', status: 'running' })],
        shots: [], sections: [], song: null,
      };
      app.renderJobs();
      const button = at('#queue-cancel-all');
      const drawn = { hidden: button.hidden, label: button.textContent };

      answer(false);
      await fire('#queue-cancel-all:click');
      const declined = { asked: asked.slice(), sent: requests.slice() };

      answer(true);
      await fire('#queue-cancel-all:click');
      await flush();
      const fired = { asked: asked.slice(), sent: requests.map((entry) => entry.path + ' ' + entry.method) };

      state.project = { id: 'p1', assets: [], jobs: [], shots: [], sections: [], song: null };
      app.renderJobs();
      console.log(JSON.stringify({
        drawn, declined, fired, idle: at('#queue-cancel-all').hidden,
      }));
    """,
        {
            "/api/projects/p1/jobs?confirm_cancel=true": {
                "body": {
                    "cancelled": [{"job_id": "j1", "label": "SHOT 01 (shot_a)"}],
                    "skipped": [],
                }
            },
        },
    )

    assert driven["drawn"] == {"hidden": False, "label": "Cancel all renders (2)"}
    # Declining asked the question and sent nothing at all.
    assert len(driven["declined"]["asked"]) == 1
    assert "Cancel 2 open renders for this project?" in driven["declined"]["asked"][0]
    assert driven["declined"]["sent"] == []
    # Accepting sent one request, to the collection route, carrying the acknowledgement.
    assert driven["fired"]["sent"][0] == "/api/projects/p1/jobs?confirm_cancel=true DELETE"
    # And the panel hides the button again once nothing is open.
    assert driven["idle"] is True


def test_the_cancellation_toast_reports_the_jobs_it_left_alone_by_name():
    """A job that settled between the click and the loop reaching it is reported, not absorbed.

    A Director who stopped nineteen of twenty-six renders has to be able to see that seven are
    still running, and under which names -- `batchReportToast`'s rule in the other direction.
    """
    toasts = run_module("""
      import { cancellationToast } from './src/music_video_producer/web/assets/api.js';
      const settled = 'This job is already complete; there is nothing running to cancel.';
      console.log(JSON.stringify({
        clean: cancellationToast({ cancelled: [{ job_id: 'j1' }, { job_id: 'j2' }], skipped: [] }),
        one: cancellationToast({ cancelled: [{ job_id: 'j1' }], skipped: [] }),
        partial: cancellationToast({
          cancelled: [{ job_id: 'j1' }],
          skipped: [{ job_id: 'j2', label: 'SHOT 07 (shot_g)', reason: settled }],
        }),
        nothing: cancellationToast({ cancelled: [], skipped: [] }),
        missing: cancellationToast(null),
      }));
    """)

    assert toasts["clean"] == "2 renders cancelled"
    assert toasts["one"] == "1 render cancelled"
    assert toasts["nothing"] == "Nothing cancelled"
    assert toasts["missing"] == "Nothing cancelled"
    assert toasts["partial"].startswith("1 render cancelled")
    assert "1 left alone." in toasts["partial"]
    # By name and with the server's own sentence, never a count on its own.
    assert "SHOT 07 (shot_g)" in toasts["partial"]
    assert "already complete" in toasts["partial"]


def test_the_clip_tells_the_running_shot_from_the_ones_queued_behind_it():
    """Item 3, executed: the phase map off the poll's own report, and what a clip draws from it.

    Nothing in this application writes `running` onto a Shot -- `generate_h3` writes `queued` and
    the reconciler writes `running` onto the *job* -- so before this a batch of twenty-six drew
    twenty-six identical `RENDERING` clips. The phase is read off the render-status report the
    poll already fetches, which is why this adds no request: `renderPhaseByShot` is pure over that
    report, exactly as `renderProgressByTarget` beside it is.
    """
    drawn = run_module("""
      import { CLIP_RENDERING_NOW_CLASS, CLIP_RENDERING_NOW_NOTE, CLIP_RENDERING_QUEUED_CLASS,
        CLIP_RENDERING_QUEUED_FLAG, CLIP_RENDERING_QUEUED_NOTE, SHOT_RENDERING_FLAG,
        clipRenderPhase, renderPhaseByShot } from './src/music_video_producer/web/assets/api.js';
      const job = (fields) => ({ id: 'j', kind: 'h3', status: 'queued', target_id: 't', ...fields });
      console.log(JSON.stringify({
        queuedFlag: CLIP_RENDERING_QUEUED_FLAG,
        runningWord: SHOT_RENDERING_FLAG,
        nowClass: CLIP_RENDERING_NOW_CLASS,
        queuedClass: CLIP_RENDERING_QUEUED_CLASS,
        nowNote: CLIP_RENDERING_NOW_NOTE,
        queuedNote: CLIP_RENDERING_QUEUED_NOTE,
        phases: renderPhaseByShot({ jobs: [
          job({ id: 'j1', target_id: 'shot_run', status: 'running' }),
          job({ id: 'j2', target_id: 'shot_wait' }),
          job({ id: 'j3', target_id: 'shot_done', status: 'complete' }),
          job({ id: 'j4', target_id: 'shot_err', status: 'error' }),
          job({ id: 'j5', target_id: 'shot_cancel', status: 'cancelled' }),
          job({ id: 'j6', kind: 'music', target_id: 'song', status: 'running' }),
          job({ id: 'j7', kind: 'flux', target_id: 'asset_w', status: 'queued' }),
          job({ id: 'j8', kind: 'ltx', target_id: 'shot_ltx', status: 'running' }),
          job({ id: 'j9', kind: 'h3', target_id: '', status: 'running' }),
        ] }),
        contested: renderPhaseByShot({ jobs: [
          job({ id: 'a', target_id: 'shot_x' }),
          job({ id: 'b', target_id: 'shot_x', status: 'running' }),
        ] }),
        contestedReversed: renderPhaseByShot({ jobs: [
          job({ id: 'b', target_id: 'shot_x', status: 'running' }),
          job({ id: 'a', target_id: 'shot_x' }),
        ] }),
        empty: renderPhaseByShot(null),
        running: clipRenderPhase('running', 42),
        runningUnknownPercent: clipRenderPhase('running', null),
        queued: clipRenderPhase('queued', 42),
        settled: clipRenderPhase('', 42),
        unknown: clipRenderPhase(undefined, undefined),
        nonsense: clipRenderPhase('complete', 42),
      }));
    """)

    # Only the two open phases, only for the kinds whose target is a shot, and never for a job
    # naming no target at all.
    assert drawn["phases"] == {"shot_run": "running", "shot_wait": "queued", "shot_ltx": "running"}
    # Two open jobs on one shot: the one ComfyUI has started is the answer, in either order.
    assert drawn["contested"] == {"shot_x": "running"}
    assert drawn["contestedReversed"] == {"shot_x": "running"}
    assert drawn["empty"] == {}

    # The running clip: its own class, the word plus the live percentage, and a sentence that
    # says which of the two states it is in -- the accessible name is the only signal a screen
    # reader announces, so the distinction has to exist there and not only in the hue.
    assert drawn["running"] == {
        "className": "rendering-now", "flag": "RENDERING 42%",
        "note": "ComfyUI is rendering this shot now.",
    }
    # An unknown percentage degrades to the bare word, never to `NaN%`.
    assert drawn["runningUnknownPercent"]["flag"] == "RENDERING"

    # The waiting clip: a different word, not a dimmer copy of the same one -- and no percentage,
    # because a shot that has not started has none and one beside QUEUED would be invented.
    assert drawn["queued"]["className"] == "rendering-queued"
    assert drawn["queued"]["flag"] == "QUEUED"
    assert drawn["queued"]["flag"] != drawn["runningWord"]
    assert "42" not in drawn["queued"]["flag"]
    assert "waiting its turn" in drawn["queued"]["note"]

    # A shot that is neither running nor queued draws nothing at all: no class, no word, no
    # sentence -- which is what makes the timeline fall back to exactly what it drew before.
    for silent in ("settled", "unknown", "nonsense"):
        assert drawn[silent] == {"className": "", "flag": "", "note": ""}, silent


def test_the_render_phase_rides_the_existing_poll_and_adds_no_request_of_its_own():
    """No new polling: the phase is a second read of the report the poll already fetched.

    Executed against the workspace so it is the real `pollRenderStatus` that fills the map, and
    counted rather than reasoned about: one tick, one request. The Director's constraint was
    explicit, and a timer or a fetch added here would be invisible to any source grep.
    """
    shot = {
        "start": 0, "duration": 4, "prompt": "One", "status": "queued", "asset_ids": [],
        "reference_labels": {}, "seed": 0, "latest_output": "", "approved_output": "",
        "locked": False,
    }
    job = {
        "kind": "h3", "status": "queued", "seed": 0, "output_files": [], "error": "",
    }
    loaded = json.dumps(
        {
            "id": "p1", "assets": [], "sections": [], "song": None,
            "jobs": [
                {**job, "id": "j1", "prompt_id": "p1", "target_id": "shot_a"},
                {**job, "id": "j2", "prompt_id": "p2", "target_id": "shot_b"},
            ],
            "shots": [
                {**shot, "id": "shot_a"},
                {**shot, "id": "shot_b", "start": 4, "prompt": "Two"},
            ],
        }
    )
    polled = run_workspace(
        f"""
      state.project = {loaded};
      requests.length = 0;
      await app.pollRenderStatus();
      await flush();
      console.log(JSON.stringify({{
        phase: state.renderPhase,
        requests: requests.map((entry) => entry.path),
        markup: at('#shots-track').innerHTML,
      }}));
    """,
        {
            "/api/projects/p1/render-status": {
                "body": {
                    "active": True,
                    "comfy_online": True,
                    "progress": [],
                    "assets": [],
                    "song": None,
                    "shots": [
                        {"shot_id": "shot_a", "status": "queued", "latest_output": ""},
                        {"shot_id": "shot_b", "status": "queued", "latest_output": ""},
                    ],
                    "jobs": [
                        {**job, "id": "j1", "prompt_id": "p1", "target_id": "shot_a",
                         "status": "running"},
                        {**job, "id": "j2", "prompt_id": "p2", "target_id": "shot_b"},
                    ],
                }
            },
        },
    )

    # One tick, one request. The phase cost nothing. The transition catalogue's single read is
    # the first render's, not the poll's, and is named rather than filtered.
    assert polled["requests"] == ["/api/projects/p1/render-status", TRANSITIONS_CATALOGUE_READ]
    assert polled["phase"] == {"shot_a": "running", "shot_b": "queued"}
    # And the two clips really draw apart, which is the whole of what the Director asked for.
    clips = {
        re.search(r'data-shot-id="(\w+)"', chunk).group(1): chunk
        for chunk in polled["markup"].split('<div class="shot-clip')[1:]
    }
    assert sorted(clips) == ["shot_a", "shot_b"], sorted(clips)
    running, waiting = clips["shot_a"], clips["shot_b"]
    assert "rendering-now" in running and "rendering-queued" not in running
    assert "rendering-queued" in waiting and "rendering-now" not in waiting
    assert ">RENDERING<" in running
    assert ">QUEUED<" in waiting
    assert "ComfyUI is rendering this shot now." in running
    assert "waiting its turn" in waiting


def test_the_two_render_phases_are_styled_apart_and_never_animated():
    """The hue is the second signal and it still has to exist; the animation must not.

    The timeline re-renders on `pointerdown`, so a keyframed pulse on the running clip would
    restart on every click of every clip -- a state that flickers under an unrelated gesture
    reads as a bug. Asserted because it is the obvious thing to reach for and it is wrong here.
    """
    styles = STYLES_CSS.read_text(encoding="utf-8")
    classes = run_module("""
      import { CLIP_RENDERING_NOW_CLASS, CLIP_RENDERING_QUEUED_CLASS }
        from './src/music_video_producer/web/assets/api.js';
      console.log(JSON.stringify([CLIP_RENDERING_NOW_CLASS, CLIP_RENDERING_QUEUED_CLASS]));
    """)
    now, waiting = classes
    rules = "\n".join(
        line
        for line in styles.splitlines()
        if f".shot-clip.{now}" in line or f".shot-clip.{waiting}" in line
    )
    assert f".shot-clip.{now} {{" in rules, now
    assert f".shot-clip.{waiting} {{" in rules, waiting
    for animated in ("animation", "@keyframes", "transition"):
        assert animated not in rules, animated


def test_the_queue_panel_ships_the_cancel_all_button_hidden_beside_the_batch_controls():
    """The markup half: the control exists, ships hidden, and carries no sentence of its own.

    Hidden in the markup for `Re-queue flagged`'s reason one element over -- a button offering to
    cancel renders on a project with none is a control whose only outcome is a refusal. Its title
    and its count come from `cancelAllPlan` at render time, so a second copy of either cannot sit
    in the HTML going stale.
    """
    markup = INDEX_HTML.read_text(encoding="utf-8")
    exported = run_module("""
      import { CANCEL_ALL_CONTROL, CANCEL_ALL_LABEL }
        from './src/music_video_producer/web/assets/api.js';
      console.log(JSON.stringify({ control: CANCEL_ALL_CONTROL, label: CANCEL_ALL_LABEL }));
    """)
    control = exported["control"].removeprefix("#")

    panel = re.search(r'<section class="panel" id="panel-queue".*?</section>', markup, re.DOTALL)
    assert panel, "the render queue panel is gone"
    actions = re.search(
        r'<div class="heading-actions">.*?id="queue-ready".*?</div>', panel.group(0), re.DOTALL
    )
    assert actions, "the queue heading actions row is gone"
    button = re.search(rf'<button[^>]*id="{control}"[^>]*>([^<]*)</button>', actions.group(0))
    assert button, f"the queue panel no longer carries #{control}"
    assert " hidden" in button.group(0), button.group(0)
    assert "title=" not in button.group(0), button.group(0)
    assert button.group(1) == exported["label"]


# --------------------------------------------------------------------------------------
# Slice C2 -- the Effects tab.
#
# Executed, not grepped. The lesson this epic paid for: a source read proves a convention and
# never a behaviour, and Epic 8 shipped a story whose pure half was tested in detail while the
# stateful half -- the part a Director actually touches -- was tested not at all, because the
# spec asked for source-text guards. So every row of this slice's matrix is run: a card added
# from a real reply, a real request fired at the real path with the real body, a real refusal
# drawn into the real panel.
# --------------------------------------------------------------------------------------

#: A catalogue in exactly the shape `effect_catalogue_report` serves, small enough to reason
#: about. The mirror test below feeds the *real* one through the same client functions, so this
#: literal cannot drift into describing a wire shape the server does not send.
#: The four reasons a parameter cannot be driven, spelled as `effects.py` spells them. Written out
#: rather than imported, because the panel shows them **whole and unparaphrased** and a test that
#: read them off the module would pass just as happily for a module that had reworded one.
DRIVE_NO_COMMANDS = "ffmpeg's {filter} filter takes no runtime commands"
DRIVE_RESIZES = (
    "driving it would resize the frame partway through the clip, which ffmpeg aborts on"
)
DRIVE_NOT_A_NUMBER = "it is not a number"

EFFECT_CATALOGUE = {
    "families": ["geometry", "texture", "grade", "stylize"],
    "effects": [
        {
            "effect": "punch_in", "family": "geometry", "label": "Punch In",
            "parameters": [{
                "name": "zoom", "label": "Zoom", "kind": "number", "default": 1.0,
                "minimum": 1.0, "maximum": 2.0, "integer": False, "choices": [],
                "drive_reason": DRIVE_RESIZES,
            }],
        },
        {
            "effect": "grain", "family": "texture", "label": "Grain",
            "parameters": [
                {"name": "strength", "label": "Strength", "kind": "number", "default": 0.0,
                 "minimum": 0.0, "maximum": 60.0, "integer": False, "choices": [],
                 "drive_reason": DRIVE_NO_COMMANDS.replace("{filter}", "noise")},
                {"name": "seed", "label": "Seed", "kind": "number", "default": 0.0,
                 "minimum": 0.0, "maximum": 65535.0, "integer": True, "choices": [],
                 "drive_reason": DRIVE_NO_COMMANDS.replace("{filter}", "noise")},
            ],
        },
        # The one drivable parameter in this catalogue, and it has to be here: Grain and Punch In
        # are both out of Epic 10's subset (R-25, R-29), so a fixture without a Grade card could
        # never draw an openable band panel at all -- which is exactly the shape of fixture that
        # makes a defect impossible to observe.
        {
            "effect": "exposure", "family": "grade", "label": "Exposure",
            "parameters": [{
                "name": "amount", "label": "Amount", "kind": "number", "default": 0.0,
                "minimum": -1.0, "maximum": 1.0, "integer": False, "choices": [],
                "drive_reason": "",
            }],
        },
        {
            "effect": "lut_look", "family": "grade", "label": "LUT Look",
            "parameters": [
                {"name": "lut", "label": "Look", "kind": "lut", "default": None,
                 "minimum": None, "maximum": None, "integer": False, "choices": [],
                 "drive_reason": DRIVE_NOT_A_NUMBER},
                {"name": "interp", "label": "Interpolation", "kind": "choice",
                 "default": "tetrahedral", "minimum": None, "maximum": None, "integer": False,
                 "choices": ["nearest", "trilinear", "tetrahedral"],
                 "drive_reason": DRIVE_NOT_A_NUMBER},
            ],
        },
    ],
    "looks": [{"lut_id": "kodak", "name": "Kodak 2383"}],
    #: `effects.DRIVE_MODES` and `effects.BINDING_SETTINGS` as the wire carries them. Neither drive
    #: is marked a default and there is nowhere for one to be marked, which is FX-14 on the wire.
    "drives": ["punch", "sustain"],
    #: `drive` names the one drive that reads a setting, or `""` for one both read.
    #: `effects.DRIVE_ONLY_SETTINGS` owns it, and it is on the wire because the panel draws these
    #: boxes and cannot answer for itself which drive would ever look at them.
    "binding_settings": [
        {"name": "band_centre", "default": 0.25, "minimum": 0.0, "maximum": 1.0, "drive": ""},
        {"name": "band_width", "default": 0.3, "minimum": 0.02, "maximum": 1.0, "drive": ""},
        {"name": "band_softness", "default": 0.35, "minimum": 0.0, "maximum": 1.0, "drive": ""},
        {"name": "floor", "default": 0.0, "minimum": 0.0, "maximum": 1.0, "drive": ""},
        {"name": "hold", "default": 0.8, "minimum": 0.0, "maximum": 10.0, "drive": "sustain"},
        {"name": "sustain", "default": 1.5, "minimum": 0.0, "maximum": 20.0, "drive": "sustain"},
    ],
}

#: The order the band panel draws its seven boxes in: the band and its floor, then depth, then the
#: sustain gate's own two timings at the foot. Written out rather than derived from the served
#: catalogue, because the grouping *is* the decision -- a test that read it off the same list the
#: panel reads would pass just as happily for a panel that had put the timings above depth.
BAND_CONTROL_ORDER = [
    "band_centre", "band_width", "band_softness", "floor", "depth", "hold", "sustain",
]

EFFECT_CATALOGUE_PATH = "/api/effects/catalogue"


def effects_shot(**overrides) -> str:
    """One Shot as the workspace holds it, as a JavaScript object literal."""
    shot = {
        "id": "shot_a", "start": 0, "duration": 4, "prompt": "rooftop wide", "mode": None,
        "asset_ids": [], "citations": [], "singing": "unknown", "seed": 1, "status": "draft",
        "prompt_id": "", "approved_output": "", "latest_output": "", "locked": False,
        "flagged": False, "effects": [],
    }
    shot.update(overrides)
    return json.dumps(shot)


#: One Parameter Binding as the wire carries it -- Exposure's amount driven by the lowest band.
#: `effects._BINDING_SETTINGS` owns the shape; this is a value in it, not a second declaration.
#: *Corrected 2026-08-27.* It carried `trigger_floor`, which `BINDING_SPEC_KEYS` does not declare
#: and `BINDING_UNKNOWN_KEY_REFUSAL` refuses by name -- inert here, because this test only reads a
#: request body, and wrong anyway: a fixture whose comment says "as the wire carries it" must carry
#: what the wire takes. The setting is `floor`.
BOUND_AMOUNT = {"parameter": "amount", "band_centre": 0, "band_width": 1, "band_softness": 0, "drive": "punch", "floor": 0.0, "depth": 0.5}


#: A Song with audio on disk, as the workspace holds one. The band panel asks two things of it --
#: is there a song, and has its render landed -- before it will look at a measurement at all, and
#: `song: null` (the default below) is one of the absences it has to name.
EFFECTS_SONG = {
    "title": "The master", "path": "song.wav", "duration": 8.0,
    "analysis": {"song_fingerprint": "abc"},
}
#: The merged snap-targets read for a song that has been measured. `analysed` is the only evidence
#: this browser has and `reason` is the server's own sentence beside it; both come off one read, so
#: the band panel and the timeline's marks cannot describe different states.
#: `band_average` and `band_edges` are here because the spectrum strip is drawn from them and
#: from nothing else (AD-26). **Six bands and seven edges, not eight and nine**: the count is read
#: off the data, and a fixture carrying the shipped count would let a literal 8 pass every test in
#: this file. The levels are deliberately uneven so a bar drawn to the wrong height is visible as
#: a number rather than as eight identical rectangles.
EFFECTS_BAND_AVERAGE = [0.42, 0.31, 0.18, 0.24, 0.09, 0.05]
EFFECTS_BAND_EDGES = [30.0, 96.0, 308.0, 985.0, 3150.0, 10080.0, 22050.0]
EFFECTS_MEASURED = {"gaps": [], "beats": [1.0, 2.0], "measured": False, "analysed": True,
                    "reason": "", "start": 0.0, "end": 8.0,
                    "envelope": {"beats": [1.0, 2.0], "band_average": EFFECTS_BAND_AVERAGE,
                                 "band_edges": EFFECTS_BAND_EDGES}}


def effects_unmeasured(reason: str) -> dict:
    """The same read for a song carrying no measurement, with the server's sentence for why."""
    return {**EFFECTS_MEASURED, "analysed": False, "reason": reason, "beats": [], "envelope": None}


def effects_project(shots: str, project_id: str = "p1", sections: str = "",
                    placed: str = "", song: dict | None = None) -> str:
    """One Project as the workspace holds it.

    `sections` and `placed` are the Section target's two halves of the wire: the Director's own
    marks, and `Project.shot_sections` — the server's answer about which section each Shot's
    midpoint lands in. They are supplied separately *on purpose*. The browser is handed the map
    and never the rule, so a fixture can hand it a map that contradicts the windows and the panel
    still has to follow the map; `test_the_section_target_follows_the_map_and_never_the_windows`
    is that fixture, and it is what fails if this client ever grows an opinion of its own.
    """
    return (
        f"{{ id: '{project_id}', jobs: [], song: {json.dumps(song)}, assets: [], messages: [], "
        f"sections: [{sections}], shot_sections: {{{placed}}}, "
        f"shots: [{shots}] }}"
    )


def run_effects_workspace(body: str, responses: dict | None = None, catalogue=EFFECT_CATALOGUE):
    """Boot the workspace with the catalogue answered (or refused) and run `body`.

    The catalogue is read once at boot, so `await flush()` at the top of every body is what lets
    the reply land before anything is drawn -- the same shape every other reply-driven test here
    uses.
    """
    canned = {EFFECT_CATALOGUE_PATH: {"body": catalogue}} if catalogue is not None else {}
    canned.update(responses or {})
    return run_workspace("await flush();\n" + body, responses=canned)


def drawn_effects_panel(shot: str, responses: dict | None = None, catalogue=EFFECT_CATALOGUE,
                        extra: str = "", song: dict | None = None,
                        measurement: dict | None = None) -> dict:
    """Select one Shot, draw the inspector, and report what the two panels ended up holding.

    The two panels are cut out of the inspector's own markup rather than read off two elements:
    the stub DOM records the markup a render wrote, and reading a nested element's `innerHTML`
    back would report the empty string for both -- which every assertion below would pass.
    """
    drawn = run_effects_workspace(f"""
      const toasts = [];
      at('#toast-region').append = (item) => toasts.push(item.textContent);
      state.project = {effects_project(shot, song=song)};
      state.songMeasurement = {json.dumps(measurement)};
      state.selectedShotId = 'shot_a';
      app.renderShotInspector();
      {extra}
      console.log(JSON.stringify({{
        html: at('#shot-inspector').innerHTML,
        activeTab: at('#shot-inspector').dataset.shotTab,
        infoHidden: Boolean(at('#shot-panel-info').hidden),
        effectsHidden: Boolean(at('#shot-panel-effects').hidden),
        infoTab: at('#shot-tab-info').attributes,
        effectsTab: at('#shot-tab-effects').attributes,
        requests: requests.map((item) => ({{ path: item.path, method: item.method, body: item.body }})),
        toasts,
      }}));
    """, responses=responses, catalogue=catalogue)
    drawn["info"], drawn["effects"] = inspector_panels(drawn["html"])
    return drawn


def count_chip(html: str) -> tuple[str, str]:
    """The tab strip's count chip as `(text, its sentence)`, read out of the inspector's markup.

    Read as a pair because the number and the sentence are one statement: the count mixes effects
    and transitions since Epic 11, so a chip that said `. 4` with no unit would be a digit a
    Director has to guess at -- which is the thing the sentence exists to stop.
    """
    found = re.search(
        r'<span class="shot-tab-count" title="([^"]*)" aria-label="([^"]*)">([^<]*)</span>', html)
    assert found, html
    assert found.group(1) == found.group(2), "the tooltip and the accessible name disagree"
    return found.group(3), found.group(1)


def without_the_transition_pair(effects_html: str) -> str:
    """The Effects tab without the two transition rows at the foot of it.

    For the sweeps that assert a marker appears *nowhere* among the effect cards. Two of those
    markers are single characters -- `EFFECT_PARAMETER_NO_READING` is one em dash -- and the
    transition rows carry ordinary prose containing them, so a panel-wide substring search stopped
    meaning what it meant the day those rows were added. The claim is about the cards, and this is
    the cards.
    """
    return effects_html.split('<div class="transition-pair">', 1)[0]


def inspector_panels(html: str) -> tuple[str, str]:
    """The `Shot Info` panel's markup and the `Effects` panel's, split out of the inspector."""
    opening = '<div class="shot-tab-panel" id="shot-panel-effects"'
    assert opening in html, html
    before, effects = html.split(opening, 1)
    assert 'id="shot-panel-info"' in before, before
    return before.split('id="shot-panel-info"', 1)[1], effects


def effects_exports() -> dict:
    return run_module("""
      import { EFFECTS_CATALOGUE_UNAVAILABLE, EFFECTS_LOCKED_NOTE, EFFECTS_REFUSAL_FLAG,
               EFFECT_ADD_LABEL, EFFECT_BIND_GLYPH, EFFECT_UNKNOWN_NOTE, CLIP_EFFECTS_CHIP,
               EFFECT_PARAMETER_NO_READING, EFFECT_PARAMETER_REFUSED_NOTE,
               EFFECT_CHOICE_REFUSED_NOTE, EFFECT_CHOICE_REFUSED_OPTION,
               EFFECT_LOOK_MISSING_NOTE, EFFECT_LOOK_MISSING_OPTION,
               EFFECT_LOOK_UNCHOSEN_NOTE, EFFECT_STACK_REFUSED_NOTE,
               EFFECT_ROW_REFUSED_CLASS, SHOT_TABS, SHOT_TAB_DEFAULT }
        from './src/music_video_producer/web/assets/api.js';
      console.log(JSON.stringify({
        unavailable: EFFECTS_CATALOGUE_UNAVAILABLE, locked: EFFECTS_LOCKED_NOTE,
        flag: EFFECTS_REFUSAL_FLAG, add: EFFECT_ADD_LABEL, bind: EFFECT_BIND_GLYPH,
        unknown: EFFECT_UNKNOWN_NOTE, chip: CLIP_EFFECTS_CHIP,
        refusedNote: EFFECT_PARAMETER_REFUSED_NOTE, noReading: EFFECT_PARAMETER_NO_READING,
        refusedClass: EFFECT_ROW_REFUSED_CLASS,
        choiceNote: EFFECT_CHOICE_REFUSED_NOTE, choiceOption: EFFECT_CHOICE_REFUSED_OPTION,
        lookMissing: EFFECT_LOOK_MISSING_NOTE, lookOption: EFFECT_LOOK_MISSING_OPTION,
        lookUnchosen: EFFECT_LOOK_UNCHOSEN_NOTE, stackNote: EFFECT_STACK_REFUSED_NOTE,
        tabs: SHOT_TABS, tabDefault: SHOT_TAB_DEFAULT,
      }));
    """)


def test_the_inspector_opens_on_two_tabs_with_shot_info_active_and_holding_what_it_held():
    """Two tabs, `Shot Info` active, and its contents unchanged.

    The last assertion is the one with teeth: `Shot Info` must contain exactly what the inspector
    contained before this slice, so every control the old panel drew is looked for inside the
    *info* panel rather than merely somewhere in the inspector -- which a control accidentally
    left outside the tabs, or drawn into the Effects panel, would also satisfy.
    """
    panel = drawn_effects_panel(effects_shot())

    assert panel["activeTab"] == "info"
    assert panel["infoHidden"] is False
    assert panel["effectsHidden"] is True
    assert panel["infoTab"]["aria-selected"] == "true"
    assert panel["effectsTab"]["aria-selected"] == "false"
    # A real tablist: each tab names the panel it owns and the panels name them back.
    assert 'role="tablist"' in panel["html"]
    assert 'aria-controls="shot-panel-info"' in panel["html"]
    assert 'aria-controls="shot-panel-effects"' in panel["html"]
    assert 'aria-labelledby="shot-tab-info"' in panel["html"]
    assert 'aria-labelledby="shot-tab-effects"' in panel["html"]
    # One tab stop, the arrows moving inside it.
    assert panel["infoTab"]["tabindex"] == "0"
    assert panel["effectsTab"]["tabindex"] == "-1"
    for control in (
        'id="shot-start"', 'id="shot-duration"', 'id="shot-mode"', 'id="shot-singing"',
        'id="shot-prompt"', 'id="shot-seed"', 'id="shot-asset-select"', 'id="shot-song-audio"',
        'id="shot-locked"', 'id="compile-shot"',
    ):
        assert control in panel["info"], control
        assert control not in panel["effects"], control


def test_the_effects_tab_carries_a_trailing_count_of_everything_the_shot_holds():
    """Including the disabled ones: a retained Effect is work the Director did.

    **And including transitions** (Epic 11's decision, 2026-08-29). `EXPERIENCE.md` said an
    Overlap transition counts toward this chip while `shotTabStrip` counted effect cards only and
    said so in its docstring; the epic that owns transitions settled it in the document's favour,
    because a Shot whose only Director work is a Dissolve would otherwise read as untouched in the
    one place the strip could say otherwise.

    The cost of that is real and is what the sentence on the chip is for: `clipEffectsChip` on the
    timeline counts effects alone and says *"Carries 1 effect"* in words, so the two numbers can
    differ. A digit whose unit has to be guessed at is what is refused here, not the difference.
    """
    empty = drawn_effects_panel(effects_shot())
    carrying = drawn_effects_panel(effects_shot(effects=[
        {"effect": "grain", "enabled": True, "parameters": {}},
        {"effect": "punch_in", "enabled": False, "parameters": {}},
    ]))
    blended = drawn_effects_panel(effects_shot(
        effects=[{"effect": "grain", "enabled": True, "parameters": {}}],
        transition_out={"type": "dissolve"},
    ))
    # A Shot with no stack at all, and one transition. The chip has to appear for this Shot: it is
    # the whole case the decision was taken for.
    only = drawn_effects_panel(effects_shot(transition_in={"type": "fade_black"}))

    assert 'class="shot-tab-count"' not in empty["html"]
    assert count_chip(carrying["html"]) == ("· 2", "2 effects and 0 transitions on this shot.")
    assert count_chip(blended["html"]) == ("· 2", "1 effect and 1 transition on this shot.")
    assert count_chip(only["html"]) == ("· 1", "0 effects and 1 transition on this shot.")


def test_the_tab_strip_moves_by_arrow_key_and_the_aria_state_follows():
    """Operated by keyboard, not read. Both arrows, both ends, and a key the strip must ignore."""
    moved = run_effects_workspace(f"""
      state.project = {effects_project(effects_shot())};
      state.selectedShotId = 'shot_a';
      app.renderShotInspector();
      const read = () => ({{
        tab: at('#shot-inspector').dataset.shotTab,
        infoHidden: Boolean(at('#shot-panel-info').hidden),
        effectsHidden: Boolean(at('#shot-panel-effects').hidden),
        info: at('#shot-tab-info').attributes['aria-selected'],
        effects: at('#shot-tab-effects').attributes['aria-selected'],
      }});
      const seen = {{ start: read() }};
      fire('#shot-tab-info:keydown', {{ key: 'ArrowRight', preventDefault() {{}} }});
      seen.right = read();
      fire('#shot-tab-effects:keydown', {{ key: 'ArrowRight', preventDefault() {{}} }});
      seen.wrapped = read();
      fire('#shot-tab-info:keydown', {{ key: 'ArrowLeft', preventDefault() {{}} }});
      seen.left = read();
      fire('#shot-tab-effects:keydown', {{ key: 'Home', preventDefault() {{}} }});
      seen.home = read();
      fire('#shot-tab-info:keydown', {{ key: 'End', preventDefault() {{}} }});
      seen.end = read();
      fire('#shot-tab-effects:keydown', {{ key: 'PageDown', preventDefault() {{}} }});
      seen.ignored = read();
      console.log(JSON.stringify(seen));
    """)

    assert moved["start"]["tab"] == "info"
    assert moved["right"]["tab"] == "effects"
    assert moved["right"]["effectsHidden"] is False
    assert moved["right"]["infoHidden"] is True
    assert moved["right"]["effects"] == "true"
    assert moved["right"]["info"] == "false"
    # Two tabs, so Right from the last one wraps to the first and Left from the first wraps back.
    assert moved["wrapped"]["tab"] == "info"
    assert moved["left"]["tab"] == "effects"
    assert moved["home"]["tab"] == "info"
    assert moved["end"]["tab"] == "effects"
    # A key this strip does not answer to leaves it exactly where it was.
    assert moved["ignored"]["tab"] == "effects"


def test_an_empty_stack_draws_the_picker_and_nothing_pretending_to_be_a_stack():
    exports = effects_exports()
    panel = drawn_effects_panel(effects_shot())

    assert escape_for_markup(exports["add"]) in panel["effects"]
    assert 'id="effect-picker"' in panel["effects"]
    # Nothing shaped like a card, and no placeholder standing in for one.
    assert 'class="effect-card' not in panel["effects"]
    assert "effect-note" not in panel["effects"]


def test_the_picker_groups_under_family_headers_in_the_servers_own_order():
    grouped = run_module(f"""
      import {{ effectPickerGroups }} from './src/music_video_producer/web/assets/api.js';
      console.log(JSON.stringify(effectPickerGroups({json.dumps(EFFECT_CATALOGUE)})));
    """)
    panel = drawn_effects_panel(effects_shot())

    assert [group["family"] for group in grouped] == ["geometry", "texture", "grade"]
    assert grouped[1]["options"] == [{"effect": "grain", "label": "Grain"}]
    # Drawn as headers over plain named buttons: no thumbnails anywhere in the picker.
    assert '<span class="effect-family">geometry</span>' in panel["effects"]
    assert 'id="effect-option-grain">Grain</button>' in panel["effects"]
    assert "<img" not in panel["effects"]


def test_an_effect_whose_family_the_served_order_forgot_is_still_offered():
    """An effect under no group is one nothing can add, which is worse than one sorted oddly.

    Unreachable through the real catalogue -- `FAMILY_ORDER` covers every entry today -- and that
    is exactly why it is asserted here: the fallback is the thing that keeps a family added to
    `effects.py` and forgotten in the order from making its effects unaddable rather than
    merely last.
    """
    forgetful = json.loads(json.dumps(EFFECT_CATALOGUE))
    forgetful["families"] = ["geometry", "grade"]
    grouped = run_module(f"""
      import {{ effectPickerGroups }} from './src/music_video_producer/web/assets/api.js';
      console.log(JSON.stringify(effectPickerGroups({json.dumps(forgetful)})));
    """)

    assert [group["family"] for group in grouped] == ["geometry", "grade", "texture"]
    assert grouped[2]["options"] == [{"effect": "grain", "label": "Grain"}]


def test_an_open_picker_survives_the_background_rebuild():
    """An open list of twenty effects is an interaction in progress too.

    Carried by the same capture/restore the tab and the held control use, rather than by a third
    mechanism -- and shut again by the choice itself, so the card that appears is the answer.
    """
    reply = {"id": "p1", "jobs": [], "song": None, "assets": [], "messages": [], "sections": [],
             "shots": [json.loads(effects_shot(effects=[
                 {"effect": "grain", "enabled": True, "parameters": {}}]))]}
    seen = run_effects_workspace(f"""
      state.project = {effects_project(effects_shot())};
      state.selectedShotId = 'shot_a';
      app.renderShotInspector();
      fire('#effect-add:click', {{}});
      app.renderShotInspector();
      const afterReload = Boolean(at('#effect-picker').hidden);
      await fire('#effect-option-grain:click', {{}});
      await flush();
      console.log(JSON.stringify({{ afterReload, afterChoice: Boolean(at('#effect-picker').hidden) }}));
    """, responses={"/api/projects/p1/shots/shot_a/effects": {"body": reply}})

    assert seen["afterReload"] is False
    assert seen["afterChoice"] is True


def test_adding_an_effect_from_the_picker_writes_the_stack_and_draws_the_card():
    """The whole gesture: open the picker, choose an effect, and let the reply redraw the panel.

    The body is asserted whole. A card added at the catalogue's defaults carries *no* parameters,
    because storage is sparse by design -- a stack full of frozen defaults is what stops a
    corrected default from ever reaching an old project.
    """
    stored = json.loads(effects_shot(effects=[
        {"effect": "grain", "enabled": True, "parameters": {}},
    ]))
    reply = {"id": "p1", "jobs": [], "song": None, "assets": [], "messages": [], "sections": [],
             "shots": [stored]}
    added = drawn_effects_panel(
        effects_shot(),
        responses={"/api/projects/p1/shots/shot_a/effects": {"body": reply}},
        extra="""
          requests.length = 0;
          await fire('#effect-option-grain:click', {});
          await flush();
          app.renderShotInspector();
        """,
    )

    assert [(item["path"], item["method"]) for item in added["requests"]] == [
        ("/api/projects/p1/shots/shot_a/effects", "PUT")
    ]
    assert json.loads(added["requests"][0]["body"]) == {"effects": [
        {"effect": "grain", "enabled": True, "parameters": {}},
    ]}
    assert 'class="effect-card ' in added["effects"]
    assert '<span class="effect-name">Grain</span>' in added["effects"]
    assert '<span class="effect-family">texture</span>' in added["effects"]
    # And the count on the tab follows the stack the server sent back.
    assert count_chip(added["html"]) == ("· 1", "1 effect and 0 transitions on this shot.")


def test_the_picker_is_a_disclosure_that_opens_and_closes_and_ships_closed():
    """`+ Effect` opens a list; it is closed until it is asked for, and it says which it is."""
    toggled = run_effects_workspace(f"""
      state.project = {effects_project(effects_shot())};
      state.selectedShotId = 'shot_a';
      app.renderShotInspector();
      const read = () => ({{
        hidden: Boolean(at('#effect-picker').hidden),
        expanded: at('#effect-add').attributes['aria-expanded'],
      }});
      const seen = {{ start: read() }};
      fire('#effect-add:click', {{}});
      seen.opened = read();
      fire('#effect-add:click', {{}});
      seen.closed = read();
      console.log(JSON.stringify(seen));
    """)

    assert toggled["start"]["hidden"] is True
    assert toggled["opened"]["hidden"] is False
    assert toggled["opened"]["expanded"] == "true"
    assert toggled["closed"]["hidden"] is True
    assert toggled["closed"]["expanded"] == "false"


def test_removing_an_effect_writes_the_shortened_stack_and_an_empty_one_is_a_real_write():
    """`{"effects": []}` is how a Director takes every card off, and it is a 200.

    Asserted as the literal body, because absence of the key is a 422 by name and a body composed
    anywhere but `effectStackWrite` is how the key goes missing.
    """
    reply = {"id": "p1", "jobs": [], "song": None, "assets": [], "messages": [], "sections": [],
             "shots": [json.loads(effects_shot())]}
    removed = drawn_effects_panel(
        effects_shot(effects=[{"effect": "grain", "enabled": True, "parameters": {}}]),
        responses={"/api/projects/p1/shots/shot_a/effects": {"body": reply}},
        extra="""
          requests.length = 0;
          await fire('#effect-remove-0:click', {});
          await flush();
          app.renderShotInspector();
        """,
    )

    assert [(item["path"], item["method"]) for item in removed["requests"]] == [
        ("/api/projects/p1/shots/shot_a/effects", "PUT")
    ]
    # The key is present and the list is empty: that is a 200, and absence of the key is a 422.
    assert json.loads(removed["requests"][0]["body"]) == {"effects": []}
    assert 'class="effect-card' not in removed["effects"]


def test_disabling_an_effect_keeps_the_card_with_its_parameters_and_writes_enabled_false():
    """A disabled Effect is retained, not hidden: FX-5, and the reason the card only dims."""
    off = json.loads(effects_shot(effects=[
        {"effect": "grain", "enabled": False, "parameters": {"strength": 12.0}},
    ]))
    reply = {"id": "p1", "jobs": [], "song": None, "assets": [], "messages": [], "sections": [],
             "shots": [off]}
    disabled = drawn_effects_panel(
        effects_shot(effects=[{"effect": "grain", "enabled": True, "parameters": {"strength": 12.0}}]),
        responses={"/api/projects/p1/shots/shot_a/effects": {"body": reply}},
        extra="""
          requests.length = 0;
          at('#effect-toggle-0').checked = false;
          await fire('#effect-toggle-0:change', {});
          await flush();
          app.renderShotInspector();
        """,
    )

    assert json.loads(disabled["requests"][0]["body"]) == {"effects": [
        {"effect": "grain", "enabled": False, "parameters": {"strength": 12.0}},
    ]}
    # The card stays, at 45% through its own class, and its controls stay drawn and readable.
    assert 'class="effect-card effect-off"' in disabled["effects"]
    assert 'id="effect-param-0-strength"' in disabled["effects"]
    assert 'value="12"' in disabled["effects"]
    assert "Grain: Disabled" in disabled["effects"]


def test_an_ordinary_stack_write_carries_a_binding_it_did_not_touch():
    """The client half of the server's adoption rule (R-33), and the half that used to fail silently.

    The server adopts a card's bindings from the stored card of the same id, so a client that
    rebuilt the stack from three keys can no longer destroy the Director's work -- it is refused by
    name instead (R-33). **Which is why the card id is asserted here too**: it is what makes the
    refusal a refusal rather than a 200, and a client that dropped it would have every ordinary
    gesture on a bound Shot answered 422.

    Driven through the real toggle rather than by calling `effectStackWrite`, so it is the
    *gesture* that is asserted to be safe.
    """
    bound = json.loads(effects_shot(effects=[
        {"id": "fx_thecardsown1", "effect": "exposure", "enabled": True,
         "parameters": {"amount": 0.2}, "bindings": [BOUND_AMOUNT]},
    ]))
    reply = {"id": "p1", "jobs": [], "song": None, "assets": [], "messages": [], "sections": [],
             "shots": [bound]}
    written = drawn_effects_panel(
        json.dumps(bound),
        responses={"/api/projects/p1/shots/shot_a/effects": {"body": reply}},
        extra="""
          requests.length = 0;
          at('#effect-toggle-0').checked = false;
          await fire('#effect-toggle-0:change', {});
          await flush();
        """,
    )

    body = json.loads(written["requests"][0]["body"])
    # The gesture landed -- and it did not cost the binding, or the id the binding is adopted by.
    assert body["effects"][0]["enabled"] is False
    assert body["effects"][0]["bindings"] == [BOUND_AMOUNT]
    assert body["effects"][0]["id"] == "fx_thecardsown1"


def test_a_card_with_no_binding_is_written_exactly_as_it_was_before_bindings_existed():
    """The other direction, because carrying sparsely is what keeps every older body byte-identical.

    A fourth or fifth key present-and-empty on every card would change every request this
    application has ever sent and would make `effectStackChanged` answer differently for two
    stacks that mean the same thing. `bindings` is carried only by a card that holds one, and
    `id` only by a card that has one -- which a card the Director has just added does not, because
    the server mints it at the moment it is stored (R-33).
    """
    plain = json.loads(effects_shot(effects=[
        {"effect": "grain", "enabled": True, "parameters": {"strength": 12.0}},
    ]))
    reply = {"id": "p1", "jobs": [], "song": None, "assets": [], "messages": [], "sections": [],
             "shots": [plain]}
    written = drawn_effects_panel(
        json.dumps(plain),
        responses={"/api/projects/p1/shots/shot_a/effects": {"body": reply}},
        extra="""
          requests.length = 0;
          at('#effect-toggle-0').checked = false;
          await fire('#effect-toggle-0:change', {});
          await flush();
        """,
    )

    assert json.loads(written["requests"][0]["body"]) == {"effects": [
        {"effect": "grain", "enabled": False, "parameters": {"strength": 12.0}},
    ]}


def test_a_landed_shots_save_leaves_this_client_holding_the_servers_own_card_ids():
    """The half of R-33 that lives in the browser, and the one a server test cannot reach.

    `PUT .../shots` owns `effects`: an existing Shot's stored stack is re-adopted whatever the body
    said, and every card arriving on a **new** Shot is minted a card id, because
    `newShotFromPlan` deep-copies the source Shot's stack, ids and all, and two Shots must not
    claim one identity. So after a Split the client's copy of the new half's card ids is wrong --
    it holds the *source's* -- and the next slider drag on that half would name a card that Shot
    does not hold, adopt no bindings onto it and be refused by name for an ordinary gesture.

    `adoptedShotEffects` is the whole of the fix: the reply is the truth for this one field. Only
    this field, because adopting the whole reply would revert a prompt typed while the write was in
    flight, and only from the save that settled the burst.
    """
    adopted = run_module("""
      import { adoptedShotEffects } from './src/music_video_producer/web/assets/api.js';
      const held = [
        { id: 'shot_one', prompt: 'edited while the write was in flight',
          effects: [{ id: 'fx_source', effect: 'exposure', parameters: { amount: 0.2 },
                      bindings: [{ parameter: 'amount', drive: 'punch', depth: 0.5 }] }] },
        // The new half, as the browser built it: the source's card id, copied.
        { id: 'shot_split', prompt: 'the second half',
          effects: [{ id: 'fx_source', effect: 'exposure', parameters: { amount: 0.2 },
                      bindings: [{ parameter: 'amount', drive: 'punch', depth: 0.5 }] }] },
        { id: 'shot_absent', effects: [{ id: 'fx_local', effect: 'grain', parameters: {} }] },
      ];
      const saved = [
        { id: 'shot_one', prompt: 'as the server had it before the edit',
          effects: [{ id: 'fx_source', effect: 'exposure', parameters: { amount: 0.2 },
                     bindings: [{ parameter: 'amount', drive: 'punch', depth: 0.5 }] }] },
        { id: 'shot_split', prompt: 'the second half',
          effects: [{ id: 'fx_minted', effect: 'exposure', parameters: { amount: 0.2 },
                     bindings: [{ parameter: 'amount', drive: 'punch', depth: 0.5 }] }] },
      ];
      const after = adoptedShotEffects(held, saved);
      console.log(JSON.stringify({
        ids: after.map((shot) => shot.effects.map((spec) => spec.id)),
        prompts: after.map((shot) => shot.prompt),
        bindings: after.map((shot) => shot.effects.map((spec) => (spec.bindings || []).length)),
        aliased: after[1].effects[0] === saved[1].effects[0],
      }));
    """)

    # The new half now names the card the server minted, so its next write adopts the right one.
    assert adopted["ids"] == [["fx_source"], ["fx_minted"], ["fx_local"]]
    # Only `effects`: the prompt the Director typed while the save was in flight is still theirs,
    # and a Shot the reply does not name is left exactly as it was.
    assert adopted["prompts"] == [
        "edited while the write was in flight", "the second half", None
    ]
    assert adopted["bindings"] == [[1], [1], [0]]
    # Copied, never aliased -- the reply object and the project on screen are two objects, and a
    # later slider move on one must not show up in the other.
    assert adopted["aliased"] is False


def test_the_shots_save_adopts_the_reply_for_the_field_that_route_owns():
    """The call site, because a pure function nothing calls is the hole `run_module` cannot see.

    Asserted on the source of `saveShotsSilently`, which no import can reach, and inside the
    settled-burst branch: adopting from a save that has been overtaken would put a stale stack on
    screen, which is the failure the revision check already exists against.
    """
    landed = without_comments(app_js_block("function saveShotsSilently(", "\n}\n"))

    assert "adoptedShotEffects(state.project.shots, saved?.shots)" in landed, landed
    settled = landed.split("if (revision === shotSaveRevision) {", 1)[1]
    assert "adoptedShotEffects" in settled, "the adoption is outside the settled-burst branch"


def test_a_slider_writes_on_release_and_paints_without_writing_while_it_is_dragged():
    """`input` paints, `change` writes. A slider that wrote per frame would hammer the route."""
    moved = json.loads(effects_shot(effects=[
        {"effect": "grain", "enabled": True, "parameters": {"strength": 30.0}},
    ]))
    reply = {"id": "p1", "jobs": [], "song": None, "assets": [], "messages": [], "sections": [],
             "shots": [moved]}
    dragged = run_effects_workspace(f"""
      state.project = {effects_project(effects_shot(effects=[
          {"effect": "grain", "enabled": True, "parameters": {"strength": 12.0}}]))};
      state.selectedShotId = 'shot_a';
      app.renderShotInspector();
      requests.length = 0;
      at('#effect-param-0-strength').value = '30';
      fire('#effect-param-0-strength:input', {{}});
      const midDrag = {{
        requests: requests.length,
        readout: at('#effect-readout-0-strength').textContent,
        stored: JSON.stringify(state.project.shots[0].effects),
      }};
      await fire('#effect-param-0-strength:change', {{}});
      await flush();
      console.log(JSON.stringify({{
        midDrag,
        requests: requests.map((item) => ({{ path: item.path, method: item.method, body: item.body }})),
      }}));
    """, responses={"/api/projects/p1/shots/shot_a/effects": {"body": reply}})

    # Held: the readout followed the thumb, nothing was sent, and the stack was not touched.
    assert dragged["midDrag"]["requests"] == 0
    assert dragged["midDrag"]["readout"] == "30.00"
    assert json.loads(dragged["midDrag"]["stored"]) == [
        {"effect": "grain", "enabled": True, "parameters": {"strength": 12.0}},
    ]
    # Released: exactly one write, carrying the number the readout was already showing.
    assert [item["path"] for item in dragged["requests"]] == [
        "/api/projects/p1/shots/shot_a/effects"
    ]
    assert json.loads(dragged["requests"][0]["body"]) == {"effects": [
        {"effect": "grain", "enabled": True, "parameters": {"strength": 30}},
    ]}


